/* A18 frozen batch: confession–congressional (80 headwords). */
'use strict';
(function (global) {
  const D=global.RA.D;
  const q=(w,n,s,p,a,b,c,x)=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType:'meaning',type:'辨义与语境',prompt:p,options:[a,b,c],answer:a,explain:x});
  const m=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
  const c=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
  const e=(w,origin,logic)=>({origin,prefix:null,root:null,suffix:null,history:[{label:'词源与演变',text:origin}],formationLogic:logic,mnemonic:null,note:'按可核实的来源关系说明，不延伸未证实的更深词根。',source:'Etymonline — https://www.etymonline.com/word/'+w});

  D('confession',{etymology:e('confession','confession 经古法语 confession 源自拉丁语 confessio「承认、供认」，来自 confiteri「承认、坦白」。','可指承认过错，也可指宗教中的告解或信仰声明。'),contexts:[c('confession.s1','法律与调查','After the detective showed him the verified recordings, Marco made a confession and admitted that he had altered the shipment records.','侦探向马尔科出示经核实的录音后，他作出供认，承认自己改动了货运记录。','After the detective showed him the verified recordings / Marco made a confession / and admitted that he had altered the shipment records.','make a confession 是“供认”；that 从句说明承认的内容。','明确承认改动记录体现 s1，而非宗教信仰声明。')],mistakes:[m('The suspect made a confession while insisting that he had done nothing wrong and denying every charge.','The suspect denied the charges rather than making a confession.','confession 是承认过错或罪行；全面否认不构成供认。')],quiz:[q('confession',1,1,'What does a confession usually contain?','an admission of something one did wrong','a list of future travel plans','a recipe for a meal','confession.s1 指承认过错或罪行。'),q('confession',2,2,'In a religious setting, confession may mean?','admitting sins to a priest','joining a sports team','buying a piece of land','宗教义 confession.s2 指向神职人员告解或信仰声明。'),q('confession',3,1,'Which action is a confession?','A driver admits that she ignored the stop sign.','A driver says she never saw the sign and did not drive there.','A driver asks where the sign is located.','承认自己违反交通规则是 confession。'),q('confession',4,2,'A statement of religious belief can be called a?','confession','conflict','configuration','confession.s2 也可指信仰声明。')]});
  D('confidentiality',{etymology:e('confidentiality','confidentiality 由 confidential 加 -ity 构成；confidential 经法语来自拉丁语 confidentia「信任、信赖」，与 confidere「信任」相关。','后缀 -ity 把 confidential 的性质转成名词，指信息须受保密的状态或原则。'),contexts:[c('confidentiality.s1','医疗伦理','The clinic explained its confidentiality policy before collecting the patient’s records, assuring her that staff would not share them without consent.','诊所收集患者病历前解释了保密政策，并保证未经同意不会向外分享。','The clinic explained its confidentiality policy / before collecting the patient’s records / assuring her that staff would not share them without consent.','confidentiality 是 policy 的名词性限定；without consent 表明保密的边界。','患者信息仅在获准时披露，体现保密原则。')],mistakes:[m('The clinic promised confidentiality and then posted the patient’s records publicly without asking her.','The clinic promised confidentiality and kept the patient’s records private unless she consented to disclosure.','未经同意公开病历直接违反 confidentiality。')],quiz:[q('confidentiality',1,1,'A confidentiality rule mainly protects?','private information from unauthorized sharing','the public release of every record','the speed of a computer','confidentiality.s1 是信息保密原则。'),q('confidentiality',2,1,'A lawyer discussing confidentiality is promising to?','keep a client’s information private','publish the client’s private letters','change the client’s name at random','保密意味着未经许可不泄露私密信息。'),q('confidentiality',3,1,'Which action breaches confidentiality?','Sending a patient’s file to strangers without consent','Locking the file in an authorized records system','Explaining privacy limits to the patient','未经同意向无关人员传送病历违反保密。'),q('confidentiality',4,1,'The noun confidentiality is closest to?','privacy of entrusted information','publicity for a new product','certainty about the weather','confidentiality 指受托信息的机密性。')]});
  D('configure',{etymology:e('configure','configure 由 con-「共同、完全」与 figure「形状、构造」构成；figure 经古法语来自拉丁语 figura「形状、形式」。','使部件按所需形式安排，现代常用于设置计算机、设备或系统。'),contexts:[c('configure.s1','软件设置','Before the first lesson, Mei configured the tablet so that the screen reader used the students’ preferred language and font size.','第一节课前，梅设置了平板电脑，使屏幕阅读器使用学生偏好的语言和字号。','Before the first lesson / Mei configured the tablet / so that the screen reader used the students’ preferred language and font size.','configure 是及物动词，tablet 作宾语；so that 从句说明配置结果。','调整设备选项使其按需要工作，正是 configure。')],mistakes:[m('The technician configured the router by leaving every required network setting unset and disconnected.','The technician configured the router by setting its network options for the office.','configure 是安排参数以使设备按选定方式工作；全部不设定不叫配置。')],quiz:[q('configure',1,1,'To configure a new printer is to?','set it up so it works as needed','throw it away without testing it','describe its color only','configure.s1 指设置硬件或软件的工作方式。'),q('configure',2,1,'Which action configures an account?','Choosing its language and security settings','Reading its name aloud','Deleting the entire service','选择语言和安全参数是在配置账户。'),q('configure',3,1,'A technician configured the network. The technician?','arranged its settings and components','wrote a poem about cables','made the network disappear','configure 表示把部件或选项安排成所需状态。'),q('configure',4,1,'Complete the meaning: configure a device for a task =?','adjust its settings for that task','ignore its settings completely','measure the task’s length','configure something for a task 是按任务需要调整设置。')]});
  D('confining',{etymology:e('confining','confining 是 confine 的现在分词形容词；confine 经法语源自拉丁语 confinia「边界、邻界」，与 finis「边界、终点」相关。','形容限制活动自由或空间局促的环境、规则或角色。'),contexts:[c('confining.s1','工作与生活','Although the office was comfortable, its rigid schedule felt confining to Nia, who could not leave even briefly to care for her child.','办公室虽舒适，僵硬的时间表却让妮娅觉得束缚，因为她连短暂离开去照顾孩子都不行。','Although the office was comfortable / its rigid schedule felt confining to Nia / who could not leave even briefly to care for her child.','confining 作表语，描述 schedule 带来的限制感；although 表示让步。','规则限制离开和个人行动自由，所以令人拘束。')],mistakes:[m('The flexible role felt confining because the employee could choose her hours and leave whenever necessary.','The flexible role felt liberating because the employee could choose her hours and leave whenever necessary.','有充分自主权的工作不符合“限制自由、令人拘束”的 confining。')],quiz:[q('confining',1,1,'A confining schedule is one that?','limits a person’s freedom to act','offers unlimited choice of hours','has no effect on anyone','confining.s1 指限制行动或自由的。'),q('confining',2,1,'Which room would feel confining?','a tiny locked room with almost no space','a spacious garden with open paths','a hall with several exits','狭小、上锁、难以活动的空间令人受限。'),q('confining',3,1,'A person calls a role confining because it?','allows little independence','provides many new options','ends at the agreed time','confining 常形容角色限制个人发展或自主性。'),q('confining',4,1,'Choose the closest opposite of confining.','liberating','restrictive','narrow','liberating 表示给予自由，与 confining 相反。')]});
  D('confirmed',{etymology:e('confirmed','confirmed 是 confirm 的过去分词及形容词；confirm 经古法语源自拉丁语 confirmare「加强、坚定」，由 con- 与 firmare「使坚固」构成。','可表示事实已证实，也可表示习惯或身份已经固定。'),contexts:[c('confirmed.s1','新闻核实','The editor published the confirmed results only after two independent laboratories repeated the test and reported the same figures.','两家独立实验室重复测试并报告相同数据后，编辑才发表已证实的结果。','The editor published the confirmed results / only after two independent laboratories repeated the test / and reported the same figures.','confirmed 作定语修饰 results；after 从句说明证实所依据的步骤。','独立重复实验使结果得到核实，符合 s1。')],mistakes:[m('The editor labeled the rumor confirmed even though no source had checked it and the figures contradicted one another.','The editor labeled the rumor unconfirmed because no source had checked it and the figures contradicted one another.','未经核查且数据矛盾的消息不能称为 confirmed。')],quiz:[q('confirmed',1,1,'A confirmed result has been?','established as true','rejected by every test','hidden from all researchers','confirmed.s1 表示经证据证实。'),q('confirmed',2,2,'A confirmed habit is?','firmly settled and unlikely to change','a new choice made once','a false report','confirmed.s2 可形容根深蒂固的习惯或信念。'),q('confirmed',3,1,'Which claim is confirmed?','Two independent tests support the same finding.','No one has checked the claim.','The evidence directly disproves it.','重复证据支持某结论时，该结论得到证实。'),q('confirmed',4,2,'A confirmed bachelor is traditionally a man who?','has long remained unmarried','has just married yesterday','is learning how to cook','confirmed.s2 指身份或习惯已稳定确立。')]});
  D('conflate',{etymology:e('conflate','conflate 经法语来自拉丁语 conflare「吹到一起、熔合」，由 con-「一起」与 flare「吹」组成。','原有的“合并、熔在一起”义引申为把不同概念混为一谈。'),contexts:[c('conflate.s1','学术写作','The review carefully distinguished correlation from causation rather than conflating the two concepts merely because they appeared in the same dataset.','这篇评论仔细区分相关性与因果关系，没有仅因二者出现在同一数据集中就把它们混为一谈。','The review carefully distinguished correlation from causation / rather than conflating the two concepts / merely because they appeared in the same dataset.','conflate A and B 表示把 A、B 混为一谈；rather than 引出对照。','相关和因果虽同现于数据中，却是不同概念，混作一谈是 conflate。')],mistakes:[m('The report conflated the two theories by clearly explaining their distinct assumptions and never treating them as the same.','The report distinguished the two theories by clearly explaining their distinct assumptions.','明确区分两套理论与 conflating 它们相反。')],quiz:[q('conflate',1,1,'To conflate two distinct ideas is to?','treat them as if they were one','prove that they are unrelated','list them in alphabetical order','conflate.s1 指把不同概念混为一谈。'),q('conflate',2,1,'A writer conflates cause and coincidence when the writer?','mistakes one for the other','carefully separates their meanings','checks each claim with evidence','把原因与巧合当成同一回事是混淆二者。'),q('conflate',3,1,'Which sentence describes conflation?','The essay uses “equality” and “identical treatment” as though they mean the same thing.','The essay defines both terms separately.','The essay gives each term a different example.','将两个不同概念当作同义项使用，体现 conflate。'),q('conflate',4,1,'A careful editor should avoid conflating?','two terms with different meanings','a title with its page number','a paragraph with its line breaks','应避免把意义不同的术语混为一谈。')]});
  D('conflicting',{etymology:e('conflicting','conflicting 是 conflict 的现在分词形容词；conflict 经法语来自拉丁语 confligere「相互撞击」，由 con-「一起」与 fligere「打击」构成。','意见、证据或要求彼此相撞，因而不一致或发生冲突。'),contexts:[c('conflicting.s1','证据评估','The two witnesses gave conflicting accounts: one placed the van outside the station, while the other said it had never been there.','两名证人的陈述互相矛盾：一人说厢式货车停在车站外，另一人却说它从未到过那里。','The two witnesses gave conflicting accounts / one placed the van outside the station / while the other said it had never been there.','conflicting 修饰 accounts；while 对比两种不能同时成立的说法。','两份陈述对同一车辆位置作出相反报告。')],mistakes:[m('The two reports were conflicting because both gave exactly the same dates, figures, and conclusion.','The two reports were consistent because both gave exactly the same dates, figures, and conclusion.','内容完全一致的报告不是 conflicting。')],quiz:[q('conflicting',1,1,'Conflicting reports?','give incompatible information','repeat the same facts exactly','contain no information at all','conflicting.s1 指互不相容或相矛盾。'),q('conflicting',2,1,'A person with conflicting duties may find that the duties?','cannot all be met at once','are identical and effortless','have already been canceled','相冲突的职责可能无法同时履行。'),q('conflicting',3,1,'Which pair of claims is conflicting?','“The door was locked” and “The door was wide open.”','“The door was locked” and “It could not be opened.”','“The door is blue” and “The wall is white.”','前两句对同一扇门的状态相互矛盾。'),q('conflicting',4,1,'Conflicting evidence should prompt a reviewer to?','investigate which accounts are reliable','assume every account is identical','ignore all differences','出现互相冲突的证据时，需要判断可靠性。')]});
  D('confluence',{etymology:e('confluence','confluence 经法语来自拉丁语 confluentia「汇流」，与 confluere「共同流动」相关，由 con-「一起」和 fluere「流」构成。','既可指河流汇合的地点，也可比喻多种因素汇聚。'),contexts:[c('confluence.s1','地理与水文','The town grew near the confluence of the two rivers, where boats could transfer cargo between the northern and southern routes.','这座城镇在两条河流的汇流处发展起来，船只可在此于南北航线之间转运货物。','The town grew near the confluence of the two rivers / where boats could transfer cargo / between the northern and southern routes.','confluence 作 near 的宾语；where 从句描述汇流处的功能。','两条河流在该地点交汇，体现地理义。')],mistakes:[m('The map marked a confluence where the river split into two branches flowing away from each other.','The map marked a river fork where the river split into two branches flowing away from each other.','confluence 是水流汇合；分叉是相反的流向关系。')],quiz:[q('confluence',1,1,'A river confluence is the place where?','two or more streams join','one river divides into separate branches','a river dries up completely','confluence.s1 指水流汇合地点。'),q('confluence',2,2,'A confluence of social factors is?','several factors coming together','one factor disappearing','a river flowing uphill','confluence.s2 可比喻多种因素汇集。'),q('confluence',3,1,'A town at the confluence of two rivers stands near?','their meeting point','their separate sources','a dry mountain peak','两河汇流处是它们相遇的位置。'),q('confluence',4,2,'A confluence of talent and funding means?','talent and funding combine','talent and funding never meet','funding is a kind of river','比喻义表示多种条件共同汇聚。')]});
  D('confluent',{etymology:e('confluent','confluent 源自拉丁语 confluent-, confluere「共同流动」，由 con- 与 fluere「流」构成；经法语或拉丁语形式进入英语。','可作形容词表示汇合、融合，也可作名词指汇入较大水流的支流。'),contexts:[c('confluent.s1','河流地貌','Below the bridge, two confluent streams formed a wider channel that carried meltwater toward the valley.','桥下，两条汇合的溪流形成更宽的河道，把融雪水带向山谷。','Below the bridge / two confluent streams formed a wider channel / that carried meltwater toward the valley.','confluent 作定语修饰 streams；that 从句修饰 channel。','溪流汇合后形成更宽水道，体现 s1。')],mistakes:[m('The confluent streams moved farther apart and never joined anywhere along the valley.','The separate streams moved farther apart and never joined anywhere along the valley.','confluent 表示汇合；彼此从未相接的水流不能称为 confluent。')],quiz:[q('confluent',1,1,'Confluent streams are streams that?','flow together and merge','flow away from one another','have no water in them','confluent.s1 表示流到一起并融合。'),q('confluent',2,2,'A confluent in river geography is?','a stream that joins a larger one','the source of a river','a dam across a river','confluent.s2 名词指汇入较大水流的支流。'),q('confluent',3,1,'Two confluent channels eventually?','combine into one flow','remain permanently isolated','turn into mountain roads','confluent 表示水流汇合。'),q('confluent',4,2,'A small river entering a larger river may be called a?','confluent','confession','constraint','作为名词，confluent 可指汇入主流的支流。')]});
  D('conformity',{etymology:e('conformity','conformity 由 conform 加 -ity 构成；conform 经法语源自拉丁语 conformare「使相似、使成形」，由 con- 与 formare「形成」组成。','名词可指遵守规范，也可指与他人保持一致或从众。'),contexts:[c('conformity.s1','安全规范','The factory’s conformity with fire-safety standards was checked before inspectors allowed the new production line to open.','检查员允许新生产线投用前，核查了工厂是否符合消防安全标准。','The factory’s conformity with fire-safety standards / was checked / before inspectors allowed the new production line to open.','conformity with 是“符合、遵守”；before 从句给出核查时间。','依照消防标准检查，体现遵守规范义。')],mistakes:[m('The laboratory demonstrated conformity with the rule by ignoring every required safety procedure.','The laboratory demonstrated nonconformity with the rule by ignoring every required safety procedure.','违反全部安全程序说明不符合规范，不是 conformity。')],quiz:[q('conformity',1,1,'Conformity with a law means?','following or meeting its requirements','deliberately breaking every requirement','writing a new law','conformity.s1 指遵守规则或标准。'),q('conformity',2,2,'Social conformity can mean?','acting in ways similar to a group','refusing to notice other people','measuring a river’s depth','conformity.s2 指行为与群体一致、随大流。'),q('conformity',3,1,'A building’s conformity to code is shown when it?','meets the official standards','violates each safety rule','has a different address','符合建筑规范体现 conformity.s1。'),q('conformity',4,2,'A teenager copies every trend to fit in; this may illustrate?','conformity','confluence','congestion','为了融入群体而模仿趋势体现从众。')]});
  D('confrontation',{etymology:e('confrontation','confrontation 由 confront 加 -ation 构成；confront 经古法语来自拉丁语 confrontare「面对、对置」，与 frons「前额、正面」相关。','名词指双方公开面对、对抗或冲突的情形。'),contexts:[c('confrontation.s1','社区协商','The meeting avoided a confrontation when the neighbors discussed the noise complaints calmly and agreed on quiet hours.','邻居们平静讨论噪声投诉并商定安静时段，会议因此避免了一场对抗。','The meeting avoided a confrontation / when the neighbors discussed the noise complaints calmly / and agreed on quiet hours.','avoid a confrontation 表示避免公开冲突；when 从句说明如何化解。','双方本可能对立，协商阻止了公开对抗。')],mistakes:[m('The discussion became a confrontation although both sides agreed immediately and no one opposed anyone.','The discussion remained a calm exchange because both sides agreed immediately and no one opposed anyone.','没有对立或冲突的平和一致讨论不是 confrontation。')],quiz:[q('confrontation',1,1,'A confrontation is most likely to involve?','open opposition between people or groups','a quiet exchange of identical views','a private weather forecast','confrontation.s1 是公开对抗或冲突。'),q('confrontation',2,1,'Which event became a confrontation?','Two groups argued face to face over the disputed land.','Two groups signed the same form without discussion.','One group went home before meeting the other.','围绕争议土地当面对抗，符合 confrontation。'),q('confrontation',3,1,'To avoid a confrontation, a mediator might?','help the sides discuss the dispute calmly','encourage both sides to threaten each other','hide all relevant information','调解人帮助平和讨论可以避免冲突升级。'),q('confrontation',4,1,'The word confrontation is closest to?','clash','agreement','confidentiality','clash 表示冲突，与 confrontation 接近。')]});
  D('confused',{etymology:e('confused','confused 是 confuse 的过去分词形容词；confuse 经古法语来自拉丁语 confundere「混合、搅在一起」，由 con-「一起」和 fundere「倾倒」构成。','混在一起难以分辨，引申为人无法理解，或事物杂乱无序。'),contexts:[c('confused.s1','课堂理解','When the lecturer changed the formula halfway through the demonstration, several students looked confused and asked which version they should use.','讲师演示到一半更换公式时，几名学生显得困惑，询问应使用哪个版本。','When the lecturer changed the formula halfway through the demonstration / several students looked confused / and asked which version they should use.','look confused 是系表结构；which 引导间接疑问句。','学生不知道该采用哪套公式，体现人的困惑义。')],mistakes:[m('The students were confused, so they understood the new formula perfectly and needed no explanation.','The students were confused, so they did not understand the new formula and needed an explanation.','confused 表示难以理解；完全理解与之矛盾。')],quiz:[q('confused',1,1,'A confused reader is someone who?','does not understand what is being read','can explain every point clearly','has memorized the text perfectly','confused.s1 指困惑、无法理解。'),q('confused',2,2,'A confused set of papers is?','mixed up and disordered','carefully sorted by date','printed in one color','confused.s2 可形容材料杂乱无序。'),q('confused',3,1,'Which person looks confused?','Someone who cannot follow the directions','Someone who explains the directions clearly','Someone who wrote the directions','无法跟上说明的人感到困惑。'),q('confused',4,2,'The files were in a confused order. They were?','disorganized','perfectly alphabetized','confidential','混乱次序指文件排列杂乱。')]});
  D('confusing',{etymology:e('confusing','confusing 是 confuse 的现在分词形容词；confuse 经法语来自拉丁语 confundere「混在一起」。','描述说明本身难懂或不同事物相似到容易被误认；与描述人的 confused 相对。'),contexts:[c('confusing.s1','产品说明','The instructions were confusing because they used three different names for the same button and never showed where it was located.','说明书令人困惑，因为它对同一个按钮用了三个不同名称，却始终没有展示按钮的位置。','The instructions were confusing / because they used three different names for the same button / and never showed where it was located.','confusing 修饰 instructions；because 从句解释造成困惑的原因。','说明不清使读者难以理解，体现 s1。')],mistakes:[m('The instructions were confusing, so every new user understood them immediately without asking questions.','The instructions were clear, so every new user understood them immediately without asking questions.','人人立即理解与说明令人困惑的意思相反。')],quiz:[q('confusing',1,1,'A confusing explanation?','is hard to understand','is perfectly clear to everyone','contains no words','confusing.s1 描述造成困惑的内容。'),q('confusing',2,2,'Two confusingly similar labels are labels that?','can easily be mistaken for each other','look completely unrelated','are both missing','confusing.s2 指相似到容易混淆。'),q('confusing',3,1,'Which is a confusing map?','one with unclear symbols and no legend','one with labeled roads and a clear key','one showing a single marked route','符号不清且无图例的地图容易使人困惑。'),q('confusing',4,1,'Confusing usually describes the _____ cause of puzzlement.','thing or information that creates it','person experiencing it','person who wrote the dictionary','confusing 修饰令人困惑的事物；人感到困惑用 confused。')]});
  D('congeal',{etymology:e('congeal','congeal 经古法语源自拉丁语 congelare「冻结、凝固」，由 con-「一起」和 gelare「冻结」构成。','液体冷却或凝结后变稠、变成固体，也可指其状态发生变化。'),contexts:[c('congeal.s1','烹饪','Once the soup cooled on the counter, the fat began to congeal into a pale layer that the cook could lift away with a spoon.','汤在台面上冷却后，脂肪开始凝结成一层浅色固体，厨师可以用勺子将其撇去。','Once the soup cooled on the counter / the fat began to congeal into a pale layer / that the cook could lift away with a spoon.','begin to congeal 描述开始凝固；that 从句修饰 layer。','脂肪由流动态变为可撇去的凝固层。')],mistakes:[m('The warm oil congealed into a thinner liquid and flowed more freely than before.','The warm oil remained liquid; cooled oil may congeal into a thicker mass.','congeal 是液体变稠或凝固；变稀并更易流动不是此义。')],quiz:[q('congeal',1,1,'When fat congeals, it?','thickens or becomes solid','turns into a lighter gas','disappears without changing','congeal.s1 表示液体凝结、凝固。'),q('congeal',2,1,'Which liquid is most likely to congeal as it cools?','melted fat','dry sand','a metal spoon','脂肪冷却后常会凝结。'),q('congeal',3,1,'If blood begins to congeal, it begins to?','form a thicker clot','boil away instantly','become fresh water','血液凝结意味着开始形成较稠的凝块。'),q('congeal',4,1,'Choose the closest meaning of congeal.','solidify','dilute','evaporate','solidify 表示凝固，与 congeal 接近。')]});
  D('congenital',{etymology:e('congenital','congenital 经法语来自中世纪拉丁语 congenitus「与生俱来的」，由 con-「共同、从一开始」与 genitus「出生的」构成，后者来自 gignere「生育」。','医学上描述出生时已存在的状况；成因可遗传，也可在出生前形成。'),contexts:[c('congenital.s1','医学','The screening found a congenital heart condition that had developed before birth, so the pediatric team arranged follow-up care immediately.','筛查发现一种出生前已经形成的先天性心脏状况，因此儿科团队立即安排了后续照护。','The screening found a congenital heart condition / that had developed before birth / so the pediatric team arranged follow-up care immediately.','congenital 修饰 condition；that 从句说明其存在时间。','出生前形成、出生时已存在，符合 congenital；不限定遗传原因。')],mistakes:[m('The doctor called the injury congenital even though it first occurred in a fall at age thirty.','The doctor called the injury acquired because it first occurred in a fall at age thirty.','成年后事故造成的新伤不是出生时已有的 congenital condition。')],quiz:[q('congenital',1,1,'A congenital condition is one that?','is present from birth','first appears only in old age','is always caused by an accident after birth','congenital.s1 指先天存在，但不一定遗传。'),q('congenital',2,1,'A congenital heart defect may have developed?','before the child was born','only after the child learned to walk','because of yesterday’s meal','先天性状况可在出生前形成。'),q('congenital',3,1,'Which case is congenital?','A baby is born with a heart condition.','An adult breaks an arm in a fall.','A runner gets a blister during a race.','出生时已有的心脏状况符合 congenital。'),q('congenital',4,1,'Does congenital necessarily mean inherited from a parent?','No; it means present from birth, whatever the cause.','Yes; every congenital condition is inherited.','No; it means first caused in adulthood.','congenital 说明存在时间，不自动说明遗传。')]});
  D('congest',{etymology:e('congest','congest 源自拉丁语 congestus，是 congerere「堆积、聚集」的过去分词；由 con-「一起」与 gerere「搬运、带来」组成。','把过多的人、车辆或分泌物挤在通道或器官里，使流动变慢或受阻。'),contexts:[c('congest.s1','城市交通','A delivery truck stalled in the tunnel and began to congest the only eastbound lane during the morning commute.','一辆货车在隧道内抛锚，早高峰期间开始堵塞唯一的东行车道。','A delivery truck stalled in the tunnel / and began to congest the only eastbound lane / during the morning commute.','congest 是及物动词，lane 作宾语；during 表示发生时段。','抛锚车辆占据道路、减慢车流，体现造成拥堵义。')],mistakes:[m('The city opened extra lanes to congest traffic, allowing every car to move faster with no bottleneck.','The city opened extra lanes to relieve traffic congestion, allowing cars to move more freely.','新增车道缓解而非造成拥堵；congest 与 relieve 的方向相反。')],quiz:[q('congest',1,1,'To congest a road is to?','fill it with traffic so movement slows','clear every vehicle from it','make its surface smoother','congest.s1 指使道路拥挤堵塞。'),q('congest',2,1,'A blocked nose may be described as congested because?','the passage is swollen or blocked','the nose is completely empty','the person has no sense of smell ever','拥堵义也可用于鼻腔堵塞或充血。'),q('congest',3,1,'Which event congests a station entrance?','A large crowd blocks the narrow doorway.','All passengers leave and the doorway is clear.','Staff widen the entrance.','人群堵住狭窄入口使通行受阻。'),q('congest',4,1,'A new road design aims to _____ the main route less.','congest','congratulate','conform','congest 作动词意为使道路等拥堵。')]});
  D('congested',{etymology:e('congested','congested 是 congest 的过去分词形容词；congest 源自拉丁语 congestus「堆积」，来自 congerere「聚集」。','可描述因交通或人群而拥堵的地方，也可描述被黏液堵塞或充血的身体部位。'),contexts:[c('congested.s1','通勤交通','We took the coastal road instead of the congested highway because traffic reports showed cars barely moving near the bridge.','我们没有走拥堵的高速公路，而改走沿海公路，因为交通报告显示桥附近的车几乎动不了。','We took the coastal road instead of the congested highway / because traffic reports showed cars barely moving near the bridge.','congested 修饰 highway；because 从句给出道路拥堵的证据。','车辆缓慢甚至不动，符合交通堵塞义。')],mistakes:[m('At rush hour the highway was congested, with no traffic and every lane completely clear.','At rush hour the highway was uncongested, with no traffic and every lane completely clear.','没有车流、车道畅通的道路不是 congested。')],quiz:[q('congested',1,1,'A congested road is?','crowded with traffic and slow to move','empty and easy to drive on','closed because of fresh paint','congested.s1 指拥挤堵塞的道路。'),q('congested',2,2,'A congested nose is?','blocked, often with mucus or swelling','moving in heavy traffic','free of all irritation','congested.s2 指鼻塞或充血。'),q('congested',3,1,'Which detail shows a city center is congested?','Cars are queued and barely moving.','Every street is empty.','Traffic lights are switched off in a garage.','排队且几乎无法前进体现交通拥堵。'),q('congested',4,2,'A doctor may ask whether a patient has a congested?','nose','highway','train station','身体部位义常用于 congested nose。')]});
  D('conglutinate',{etymology:e('conglutinate','conglutinate 经拉丁语 conglutinare「黏合在一起」进入英语，由 con-「一起」与 gluten「胶、黏质」相关成分构成。','动词表示使物体黏合成一团，或自身黏连；现代使用较少。'),contexts:[c('conglutinate.s1','材料科学','The resin began to conglutinate the loose fibers into a single sheet as the curing process removed moisture from the mixture.','树脂在固化过程除去混合物中的水分时，开始把松散纤维黏合成一张整体薄片。','The resin began to conglutinate the loose fibers / into a single sheet / as the curing process removed moisture from the mixture.','conglutinate A into B 表示把 A 黏合成 B；as 引出同时发生的过程。','纤维因树脂而黏结成整体，符合该词的黏连义。')],mistakes:[m('The adhesive conglutinated the sheets by keeping them separate and preventing any contact between them.','The adhesive conglutinated the sheets by bonding them together.','conglutinate 表示黏合；保持分离且防止接触与其含义相反。')],quiz:[q('conglutinate',1,1,'To conglutinate two pieces of material is to?','glue them together','separate them completely','measure their weight','conglutinate.s1 指黏合成一体。'),q('conglutinate',2,1,'If blood cells conglutinate, they?','stick together in a mass','turn into separate gases','move farther apart','该动词也可描述细胞或物质黏聚在一起。'),q('conglutinate',3,1,'Which process conglutinates fibers?','Resin bonds the fibers into one sheet.','A blade cuts each fiber apart.','Water washes every fiber away.','树脂将纤维黏结为整体即 conglutinate。'),q('conglutinate',4,1,'Choose the nearest verb to conglutinate.','adhere','scatter','dissolve','adhere 表示黏附，与 conglutinate 接近。')]});
  D('congratulation',{etymology:e('congratulation','congratulation 由 congratulate 加 -ion 构成；congratulate 经拉丁语 congratulari「共同庆贺」而来，由 con-「共同」与 gratulari「表示欣喜、祝贺」组成。','常用复数 congratulations 表达对成功的祝贺，也可指一封正式贺信。'),contexts:[c('congratulation.s1','毕业典礼','After the final examination results were posted, friends filled the graduate’s phone with congratulations on earning the scholarship.','期末成绩公布后，朋友们纷纷发消息祝贺这名毕业生获得奖学金。','After the final examination results were posted / friends filled the graduate’s phone with congratulations / on earning the scholarship.','congratulations 常用复数；on 后接名词或动名词，说明祝贺缘由。','朋友因奖学金成功向毕业生表示祝贺，体现 s1。')],mistakes:[m('She sent congratulations on his failure and praised him for losing the competition.','She sent condolences on his failure and congratulated him on his later recovery.','congratulation 表达赞贺成功；对失败表示同情应使用 condolences。')],quiz:[q('congratulation',1,1,'“Congratulations on your promotion” expresses?','praise for someone’s success','anger about a mistake','a request for private information','congratulation.s1 用于祝贺成功。'),q('congratulation',2,2,'A formal congratulation may be?','a written message praising an achievement','a bill for medical treatment','an order to stop working','congratulation.s2 可指正式贺信或贺辞。'),q('congratulation',3,1,'Which phrase is idiomatic?','Congratulations on passing the exam.','Congratulations at pass the exam.','A congratulation for you passed.','常用结构是 congratulations on + 名词或动名词。'),q('congratulation',4,1,'A team wins a championship. What might its rivals send?','congratulations','a confidentiality notice','a traffic report','对获胜队伍表达祝贺可说 congratulations。')]});
  D('congressional',{etymology:e('congressional','congressional 由 congress 加 -ional 构成；congress 经古法语来自拉丁语 congressus「相遇、聚会」，与 congredi「走到一起」相关。','形容属于国会或议会，尤其美国联邦国会，或由其作出。'),contexts:[c('congressional.s1','美国政治','The congressional committee released its budget report after members questioned agency officials about the proposed spending cuts.','国会委员会在成员就拟议削减开支质询机构官员后，公布了预算报告。','The congressional committee released its budget report / after members questioned agency officials / about the proposed spending cuts.','congressional 作定语修饰 committee；after 从句说明报告发布时间。','由国会组成的委员会开展预算审查，符合国会义。')],mistakes:[m('The congressional committee was a private neighborhood club with no connection to any legislature.','The congressional committee was a committee of a legislature, such as the US Congress.','与任何立法机构无关的私人俱乐部不是 congressional committee。')],quiz:[q('congressional',1,1,'A congressional hearing is connected with?','a legislature, especially the US Congress','a private cooking school','a river junction','congressional.s1 指国会或议会的。'),q('congressional',2,1,'Which is a congressional action?','A US House committee examines a bill.','A town baker decorates a cake.','A river divides into two streams.','国会委员会审议法案属于 congressional action。'),q('congressional',3,1,'A congressional district is a district represented in?','a legislature','a hospital ward','a music conservatory only','该词形容与议会代表制度有关的选区。'),q('congressional',4,1,'The adjective congressional comes from which noun?','congress','conscience','confluence','congressional 由 congress 加形容词后缀构成。')]});
  D('congressman',{etymology:e('congressman','congressman 是 congress 与 man 的复合词；congress 经法语来自拉丁语 congressus「聚会、相遇」，指立法会议或其成员。','可泛指国会议员；在美国用法中尤指男性众议员。'),contexts:[c('congressman.s2','美国政府','The district elected a new congressman to the US House of Representatives, and he took office after the January swearing-in.','该选区选出一名新任美国众议员，他在一月宣誓就职后开始履职。','The district elected a new congressman / to the US House of Representatives / and he took office after the January swearing-in.','congressman 是 elected 的宾语；to 指明所当选机构。','美国众议院成员对应 s2。')],mistakes:[m('The state sent its congressman to the Senate, where he served as one of its appointed senators.','The state sent its senator to the Senate, where he served as one of its senators.','美国 congressman 通常指众议员；参议员是 senator。')],quiz:[q('congressman',1,1,'A congressman generally serves as a member of?','a legislature','a hospital team','a river authority','congressman.s1 指国会议员。'),q('congressman',2,2,'In the United States, a congressman is specifically a male member of the?','House of Representatives','Supreme Court','Cabinet only','美国用法常特指男性众议员。'),q('congressman',3,1,'Which official is elected to represent a district in the US House?','a congressman','a consul','a connoisseur','众议院选区代表可称 congressman。'),q('congressman',4,1,'A congressman votes on?','legislation','medical prescriptions','river currents','国会议员参与立法表决。')]});
  D('congruent',{etymology:e('congruent','congruent 源自拉丁语 congruent-, congruere「相合、一致」，经拉丁语形式进入英语。','几何学指形状和大小相同；一般义指与某物相符合或协调。'),contexts:[c('congruent.s1','几何学','The teacher overlaid the two paper triangles and showed that every side and angle matched, so the figures were congruent.','老师把两张纸三角形叠在一起，展示每条边和每个角都相等，因此这两个图形全等。','The teacher overlaid the two paper triangles / and showed that every side and angle matched / so the figures were congruent.','congruent 作表语形容词；so 引出叠合结果。','对应边角均相等，符合几何全等义。')],mistakes:[m('The two triangles were congruent although one was twice as large and their corresponding angles differed.','The two triangles were similar but not congruent because their sizes and corresponding angles differed.','全等要求形状和大小都相同；大小不同的图形不全等。')],quiz:[q('congruent',1,1,'In geometry, congruent figures have the same?','shape and size','color and material only','position on the page','congruent.s1 指形状和大小均相同。'),q('congruent',2,2,'A statement congruent with the evidence is?','in agreement with the evidence','unrelated to every fact','larger than the evidence','一般义表示相符合、一致。'),q('congruent',3,1,'Two congruent squares must have?','equal side lengths','different numbers of corners','different shapes','全等方形的边长相同。'),q('congruent',4,2,'A policy congruent with the stated goal?','fits or agrees with that goal','contradicts it completely','has no connection to it','congruent.s2 指与目标一致。')]});
  D('congruity',{etymology:e('congruity','congruity 由 congruous 加 -ity 构成；congruous 源自拉丁语 congruus「相合的」，与 congruere「相合、一致」相关。','表示事物之间的协调、一致或彼此适配。'),contexts:[c('congruity.s1','视觉设计','The designer checked the congruity between the building’s modern entrance and its older stone facade before approving the renovation plan.','设计师批准翻修方案前，检查了建筑现代入口与旧石立面之间是否协调。','The designer checked the congruity between the building’s modern entrance and its older stone facade / before approving the renovation plan.','congruity between A and B 表示 A 与 B 的协调性。','设计元素彼此适配与否是 congruity 的核心。')],mistakes:[m('The incongruity of the color scheme was evident because every shade matched perfectly and no element clashed.','The congruity of the color scheme was evident because every shade matched and no element clashed.','所有颜色协调匹配时，说明 congruity 而非 incongruity。')],quiz:[q('congruity',1,1,'Congruity between two parts means their?','agreement or harmony','complete separation','relative weight','congruity.s1 指协调、一致。'),q('congruity',2,1,'A reviewer notices congruity when?','the design elements fit together','every element clashes','the parts have been removed','彼此适配的设计体现 congruity。'),q('congruity',3,1,'Which pairing shows congruity?','A formal invitation with a formal event','A beach towel as the only tablecloth at a state banquet','A winter coat worn in a tropical pool','风格与场合相配体现协调。'),q('congruity',4,1,'The closest opposite of congruity is?','incongruity','agreement','harmony','incongruity 表示不协调，与 congruity 相反。')]});
  D('coniferous',{etymology:e('coniferous','coniferous 由 conifer 加形容词后缀 -ous 构成；conifer 源自拉丁语 conifer「结球果的」，由 conus「圆锥、球果」与 ferre「携带」组成。','形容结球果的树木，通常指松、杉等针叶树。'),contexts:[c('coniferous.s1','森林生态','The coniferous forest stayed green through winter, and its pine trees provided shelter for birds when deciduous branches were bare.','这片针叶林整个冬天保持绿色；落叶树枝变秃时，松树仍为鸟类提供庇护。','The coniferous forest stayed green through winter / and its pine trees provided shelter for birds / when deciduous branches were bare.','coniferous 作定语修饰 forest；when 从句形成季节对比。','常绿松树及其球果特征符合针叶树义。')],mistakes:[m('The botanist classified the oak, which bears acorns and broad leaves, as a coniferous tree.','The botanist classified the pine, which bears cones and needle-like leaves, as a coniferous tree.','橡树结橡果且有阔叶，不是结球果的针叶树。')],quiz:[q('coniferous',1,1,'A coniferous tree typically bears?','cones','acorns only','flowers with no seeds','coniferous.s1 指结球果的树木。'),q('coniferous',2,1,'Which forest is coniferous?','one dominated by pines and firs','one made entirely of broadleaf oaks','one containing only grasses','松树和冷杉是典型针叶树。'),q('coniferous',3,1,'Needle-like leaves are common among?','coniferous trees','mushrooms','deciduous fruit bushes only','针叶树常有针状叶。'),q('coniferous',4,1,'A pine is a conifer because it?','produces cones','produces acorns','has no woody stem','conifer 与结球果的特征相关。')]});
  D('conjectural',{etymology:e('conjectural','conjectural 由 conjecture 加 -al 构成；conjecture 经法语源自拉丁语 coniectura「推测」，来自 conicere「投掷到一起、推断」。','表示基于推测而非确凿证据。'),contexts:[c('conjectural.s1','历史研究','Because no letters from that year survive, the proposed reason for the minister’s resignation remains conjectural rather than an established fact.','由于那一年没有信件留存，关于部长辞职原因的说法仍属推测，而非已确立事实。','Because no letters from that year survive / the proposed reason for the minister’s resignation remains conjectural / rather than an established fact.','remain conjectural 是系表结构；rather than 对照确证事实。','缺乏直接材料说明该解释只是假说。')],mistakes:[m('The archaeologist called the conclusion conjectural after finding a signed document that directly proved it.','The archaeologist called the conclusion well-supported after finding a signed document that directly proved it.','直接证明结论的证据与仅凭猜测的 conjectural 相反。')],quiz:[q('conjectural',1,1,'A conjectural explanation is?','based on a guess or inference','proved beyond doubt by direct evidence','copied from a signed contract','conjectural.s1 表示推测性的、未证实的。'),q('conjectural',2,1,'A claim with no surviving records may remain?','conjectural','confirmed','conclusive','缺乏记录时的解释可能只是推测。'),q('conjectural',3,1,'Which phrase best matches conjectural?','a tentative theory','an established measurement','a verified transcript','tentative theory 尚待验证，与 conjectural 接近。'),q('conjectural',4,1,'Researchers should label a conjectural account as?','uncertain, not proven','certainly true','a direct quotation','推测性叙述应明确标为不确定。')]});
  D('conjure',{etymology:e('conjure','conjure 经古法语源自拉丁语 coniurare「共同起誓」，由 con- 与 iurare「发誓」组成；英语后来发展出施法、凭空变出及唤起记忆等义。','根据语境可指魔术般变出事物，也可指使某幅景象或回忆浮现。'),contexts:[c('conjure.s2','回忆与感官','The smell of wet cedar conjured memories of the cabin where Jo spent each summer with her grandparents.','潮湿雪松的气味唤起乔每年夏天与祖父母在小木屋度过时光的回忆。','The smell of wet cedar / conjured memories of the cabin / where Jo spent each summer with her grandparents.','conjure memories of 是唤起回忆的搭配；where 从句修饰 cabin。','气味使过去的画面在脑中浮现，对应 s2。')],mistakes:[m('The scent conjured a memory by ensuring that Jo forgot the cabin and could not picture it at all.','The scent erased the memory because Jo forgot the cabin and could not picture it at all.','完全忘掉且无法想起不符合 conjure a memory。')],quiz:[q('conjure',1,1,'A magician conjures a rabbit when she?','makes it appear as if by magic','writes a report about rabbits','lets it walk away unseen','conjure.s1 可指用魔术使物体出现。'),q('conjure',2,2,'A familiar song can conjure?','a vivid memory','a legal signature','a river junction','conjure.s2 指唤起回忆或心中景象。'),q('conjure',3,1,'Which sentence uses conjure to mean “produce seemingly from nowhere”?','The cook conjured a full meal from a few leftovers.','The cook forgot every ingredient.','The cook measured the oven temperature.','从少量剩菜变出一桌饭菜是比喻性的凭空弄出。'),q('conjure',4,2,'The word “home” may conjure images of?','familiar rooms and family','a traffic jam only','a list of unrelated numbers','一个词能唤起有关家的画面。')]});
  D('connective',{etymology:e('connective','connective 由 connect 加 -ive 构成；connect 经法语来自拉丁语 connectere「系在一起」，由 con- 与 nectere「编结、连接」组成。','形容具有连接作用，也可作名词指连接句子成分的词或结构。'),contexts:[c('connective.s2','语法','In the sentence “We stayed inside because the roads were icy,” the connective because links the reason to the decision.','在“We stayed inside because the roads were icy”这句话中，连接词 because 把原因与决定连接起来。','In the sentence / the connective because / links the reason to the decision.','connective 作名词；because 引导原因从句并连接两个分句。','该词把原因与主句建立逻辑关系，符合 s2。')],mistakes:[m('In “I stayed home because it rained,” the word “because” is a connective that separates the clauses without linking them.','In “I stayed home because it rained,” “because” is a connective that links the reason clause to the main clause.','because 的功能是连接并引出原因从句，而非把句子割裂。')],quiz:[q('connective',1,1,'A connective tissue or wire has the function of?','joining parts together','making parts more distant','removing all contact','connective.s1 表示连接性的。'),q('connective',2,2,'In grammar, “and” can be a?','connective linking words or clauses','noun naming a river','verb meaning to freeze','and 是连接词，可连接词语或分句。'),q('connective',3,2,'Which word is a connective in “I left because it was late”?','because','late','left','because 连接主句和原因从句。'),q('connective',4,1,'A connective cable is one that?','links one device to another','stores food','blocks every signal by design','connective.s1 表示起连接作用的。')]});
  D('connexion',{etymology:e('connexion','connexion 是 connection 的历史拼写变体；connection 经古法语源自拉丁语 connectere「连接、系在一起」。','可指人与事物之间的关联，也可指实际的物理连接；现代英语更常写 connection。'),contexts:[c('connexion.s1','语言与关系','The historian found a connexion between the two letters because both used the same rare phrase and referred to the same meeting.','历史学家发现两封信之间有联系，因为它们都使用同一个罕见短语，并提到同一场会议。','The historian found a connexion between the two letters / because both used the same rare phrase / and referred to the same meeting.','connexion between A and B 表示 A 与 B 之间的关联。','共享罕见短语并提到同一会议构成两信之间的关联。')],mistakes:[m('The historian denied any connexion between the letters while demonstrating that both contained the same unique passage.','The historian found a connexion between the letters because both contained the same unique passage.','相同独特段落提供了明显联系，与否认任何关联矛盾。')],quiz:[q('connexion',1,1,'A connexion between two events is a?','link or relationship','complete lack of contact','type of tree cone','connexion.s1 指关系或联系。'),q('connexion',2,1,'Which spelling is more common in modern English?','connection','connextion','conection','connexion 是 connection 的较旧拼法。'),q('connexion',3,1,'A telephone connexion allows people to?','communicate through a link','avoid all communication','grow a plant indoors','物理或通信连接使双方能够联系。'),q('connexion',4,1,'A researcher looks for a connexion between two records to find?','how they are related','their paper color only','which one weighs more','研究关联是查明记录如何相互联系。')]});
  D('connivance',{etymology:e('connivance','connivance 源自法语 connivence 或拉丁语 conniventia，与 connivere「眯眼、装作没看见」有关。','指对不当行为的默许，也可指与他人秘密串通参与不法行为。'),contexts:[c('connivance.s1','职场调查','The theft continued for months with the guard’s connivance, since he saw the unauthorized exits but deliberately never reported them.','在保安的默许下，盗窃持续了数月；他看见未经许可的货物被运出，却故意不报告。','The theft continued for months with the guard’s connivance / since he saw the unauthorized exits / but deliberately never reported them.','with someone’s connivance 表示在某人默许下；since 说明原因。','保安知情却故意纵容，体现 s1。')],mistakes:[m('The guard was accused of connivance even though he reported the theft immediately and helped stop it.','The guard was praised for reporting the theft immediately and helping stop it.','及时报告并制止违法行为不属于默许或包庇。')],quiz:[q('connivance',1,1,'A person acts with connivance when they?','knowingly allow wrongdoing to continue','report wrongdoing as soon as they see it','accidentally discover a harmless mistake','connivance.s1 指默许或纵容不法行为。'),q('connivance',2,2,'Connivance in a fraud can involve?','secret cooperation in the wrongdoing','public opposition to the fraud','an unrelated financial audit','connivance.s2 指秘密共谋。'),q('connivance',3,1,'A supervisor sees theft and deliberately hides it. This is?','connivance','congruence','congestion','明知盗窃却刻意隐瞒属于默许包庇。'),q('connivance',4,1,'Which action contradicts connivance?','reporting the misconduct and helping stop it','silently permitting it','secretly helping it succeed','主动揭发并制止不当行为与 connivance 相反。')]});
  D('connive',{etymology:e('connive','connive 经法语源自拉丁语 connivere「眯眼、装作没看见」，英语中形成“默许不当行为”及“秘密共谋”两义。','通常与 at 表示默许某事，也可与 with 表示和他人串通。'),contexts:[c('connive.s2','商业舞弊','The two managers connived with a supplier to submit false invoices and divide the payments before the audit began.','两名经理与供应商串通提交虚假发票，并在审计开始前瓜分款项。','The two managers connived with a supplier / to submit false invoices / and divide the payments before the audit began.','connive with someone to do something 表示与某人合谋做某事。','经理与供应商秘密合作实施舞弊，符合 s2。')],mistakes:[m('The auditor connived with the supplier by exposing their false invoices and giving the evidence to investigators.','The auditor exposed the false invoices and gave the evidence to investigators.','揭露舞弊而非与供应商合谋，不是 connive with。')],quiz:[q('connive',1,1,'To connive at misconduct is to?','secretly tolerate it','publicly report it','accidentally cause it','connive.s1 指暗中默许不当行为。'),q('connive',2,2,'Two officials connive with a contractor when they?','secretly cooperate in wrongdoing','compete fairly for a contract','publish an independent audit','connive.s2 表示秘密串通。'),q('connive',3,1,'Which sentence uses connive correctly?','The guard connived at the theft by ignoring it.','The guard connived the theft to stop it.','The guard connived with the report honestly.','connive at something 是默许某事的常见结构。'),q('connive',4,2,'A manager and supplier secretly plan fake billing. They?','connive with each other','congeal with each other','conform with the weather','秘密合谋虚假收费体现串通义。')]});
  D('connoisseur',{etymology:e('connoisseur','connoisseur 经法语 connaisseur 来自 connaître「认识、了解」，源自拉丁语 cognoscere「认识」。','指能凭专业知识或经验判断艺术、食物、葡萄酒等质量的人，也可泛指某领域行家。'),contexts:[c('connoisseur.s2','收藏鉴赏','As a connoisseur of antique maps, Dr. Rao could identify the printer from the border design before reading the date.','作为古地图行家，拉奥博士甚至不用看日期，便能从边框设计辨认出印刷者。','As a connoisseur of antique maps / Dr. Rao could identify the printer from the border design / before reading the date.','connoisseur of + 领域表示该领域的鉴赏行家。','凭专业知识识别地图细节，体现泛领域行家义。')],mistakes:[m('The connoisseur of paintings could not distinguish a signed original from a blank sheet and had never studied art.','The novice could not distinguish a signed original from a blank sheet and had never studied art.','缺少鉴赏知识、无法判断作品者不是 connoisseur。')],quiz:[q('connoisseur',1,1,'A wine connoisseur can?','judge the quality of wine with expertise','make wine disappear by magic','repair a congested road','connoisseur.s1 指艺术或饮食鉴赏家。'),q('connoisseur',2,2,'A connoisseur of chess is?','a person with deep knowledge of chess','a person who has never seen a chessboard','a type of chess piece','connoisseur.s2 可泛指某领域的行家。'),q('connoisseur',3,1,'Which person is a connoisseur of paintings?','An expert who can assess their style and quality','A visitor who cannot tell paintings from posters','A guard who locks the gallery','鉴赏家能凭知识判断绘画质量。'),q('connoisseur',4,2,'“A connoisseur of jazz” means?','a knowledgeable jazz expert','a musician’s instrument','a concert ticket','of 后的领域说明 connoisseur 擅长的主题。')]});
  D('connote',{etymology:e('connote','connote 由 con-「共同、附加」与 note「标记、注意」构成，源自拉丁语 connotare「共同标记」。','指词语除字面意义外还带有暗示或联想。'),contexts:[c('connote.s1','词语含义','Although “inexpensive” and “cheap” can both describe a low price, “cheap” may connote poor quality in this advertisement.','虽然 inexpensive 和 cheap 都能描述价格低，但在这则广告中 cheap 可能暗含质量差的意味。','Although “inexpensive” and “cheap” can both describe a low price / “cheap” may connote poor quality / in this advertisement.','connote 的宾语是附加联想 poor quality；although 引出让步。','cheap 除低价外还带有质量差的联想。')],mistakes:[m('The word “slim” connotes exactly the same neutral meaning in every context and never suggests anything extra.','The word “slim” can connote additional ideas, such as attractiveness or insufficient size, depending on context.','connote 指语境中附带的联想，不保证完全没有额外暗示。')],quiz:[q('connote',1,1,'A word connotes an idea when it?','suggests it in addition to its literal meaning','spells it backward','has no meaning at all','connote.s1 指隐含或使人联想到额外含义。'),q('connote',2,1,'“Childish” may connote?','immaturity beyond simply being young','a precise age in years only','a type of river','该词可能带有幼稚、不成熟的附加联想。'),q('connote',3,1,'A neutral term is changed to a loaded term that _____ disrespect.','connotes','congeals','conforms','带有不敬附加意味用 connote。'),q('connote',4,1,'The literal meaning of a word differs from what it may?','connote','congest','consecrate','connote 描述字面义之外的暗示。')]});
  D('connubial',{etymology:e('connubial','connubial 源自拉丁语 connubialis「婚姻的」，与 connubium「婚姻」相关；该词由 con- 与 nubere「结婚」构成。','形容婚姻或夫妻生活，语体较正式或略带幽默。'),contexts:[c('connubial.s1','婚姻生活','The columnist joked that their connubial peace depended on keeping two coffee makers, since each spouse preferred a different brew.','专栏作者打趣说，他们的夫妻和睦全靠保留两台咖啡机，因为夫妻俩喜欢不同的冲煮方式。','The columnist joked / that their connubial peace depended on keeping two coffee makers / since each spouse preferred a different brew.','connubial 修饰 peace，指婚姻关系中的和睦；since 从句解释缘由。','夫妻共同生活关系对应婚姻义。')],mistakes:[m('The connubial partners had never married and lived on separate continents without any relationship.','The connubial partners were spouses sharing married life.','connubial 指婚姻、夫妻关系；无婚姻且毫无关系不适用。')],quiz:[q('connubial',1,1,'Connubial life concerns?','marriage and married partners','a legislative session','a river junction','connubial.s1 指婚姻或夫妻生活。'),q('connubial',2,1,'A connubial home is a home shared by?','spouses','business competitors','river fish','夫妻共同居住的家与婚姻有关。'),q('connubial',3,1,'Which phrase uses connubial naturally?','connubial harmony between the spouses','connubial traffic on the highway','connubial branches of a pine','connubial 可修饰夫妻生活或婚姻和谐。'),q('connubial',4,1,'The nearest meaning of connubial is?','marital','congressional','coniferous','marital 表示婚姻的，与 connubial 同义。')]});
  D('conqueror',{etymology:e('conqueror','conqueror 由 conquer 加施事后缀 -or 构成；conquer 经古法语 conquerre 来自拉丁语 conquirere「寻求、取得」。','指以武力控制土地的人，也可泛指战胜敌人或克服艰难任务的人。'),contexts:[c('conqueror.s1','古代史','The conqueror occupied the coastal kingdom and installed a governor to collect taxes for the new empire.','征服者占领了沿海王国，并任命总督为新帝国征税。','The conqueror occupied the coastal kingdom / and installed a governor / to collect taxes for the new empire.','conqueror 作主语；to-infinitive 表示任命总督的目的。','凭军事力量控制他国领土，符合 s1。')],mistakes:[m('The conqueror peacefully visited the kingdom, left its government untouched, and took control of no land.','The visitor peacefully visited the kingdom without conquering it or taking control of its land.','没有夺取控制权的和平访客不是征服者。')],quiz:[q('conqueror',1,1,'A historical conqueror is someone who?','takes control of land by force','writes a peaceful travel guide','repairs old buildings','conqueror.s1 指以武力征服土地的人。'),q('conqueror',2,2,'A conqueror of fear is a person who?','overcomes a serious difficulty','creates a new fear','avoids every challenge forever','conqueror.s2 可比喻克服困难者。'),q('conqueror',3,1,'Which figure is a conqueror in the military sense?','A general who captures and rules another territory','A diplomat who negotiates a trade deal','A historian who studies an empire','以军事力量夺地并统治者符合 s1。'),q('conqueror',4,2,'Someone who finally masters a difficult climb may be called a?','conqueror of the challenge','confluent of the mountain','confession of the route','比喻义可指克服重大挑战的人。')]});
  D('conquest',{etymology:e('conquest','conquest 经古法语 conqueste 来自拉丁语 conquirere「寻求、取得」；与 conquer 同源。','指武力夺取领土的行为，也可指取得的对象、猎获物或成功赢得的人。'),contexts:[c('conquest.s1','军事史','The conquest of the island took several months because the defenders controlled the harbor and the mountain roads.','由于守军控制了港口和山路，对该岛的征服持续了数月。','The conquest of the island took several months / because the defenders controlled the harbor and the mountain roads.','conquest of + 地点表示对该地的征服；because 说明耗时原因。','通过军事行动夺取控制权体现 s1。')],mistakes:[m('The conquest was complete even though the invading army withdrew without taking control of any territory.','The invasion failed because the army withdrew without conquering any territory.','未取得土地控制权的撤军不构成完成征服。')],quiz:[q('conquest',1,1,'The conquest of a territory is the act of?','taking control of it by force','building a school there','mapping its rivers','conquest.s1 指武力征服。'),q('conquest',2,2,'A “conquest” in a personal story might be?','something or someone successfully won','a rule that was never followed','a private medical consultation','conquest.s2 可指取得的成果或赢得的人。'),q('conquest',3,1,'Which phrase refers to a military takeover?','the conquest of the kingdom','the consultation with a doctor','the confluence of streams','对王国的军事征服对应 conquest.s1。'),q('conquest',4,2,'In an old romantic story, a new conquest might be?','a person the hero has just won over','a river joining the sea','a country’s written constitution','比喻义可指新赢得的恋爱对象。')]});
  D('conscience',{etymology:e('conscience','conscience 经古法语来自拉丁语 conscientia「共同知晓、良知」，与 conscire「共同知道」相关。','指内心判断行为对错的道德意识。'),contexts:[c('conscience.s1','道德选择','Although nobody would have discovered the mistake, Hana’s conscience led her to return the extra change to the cashier.','尽管没人会发现这个错误，哈娜的良心还是促使她把多找的钱还给收银员。','Although nobody would have discovered the mistake / Hana’s conscience led her to return the extra change / to the cashier.','conscience 作主语；lead someone to do 表示促使某人行动。','内在道德判断驱使她归还多找的钱。')],mistakes:[m('His conscience told him the theft was wrong, so he proudly stole the wallet and felt no moral concern.','Despite knowing the theft was wrong, he ignored his conscience and stole the wallet.','conscience 提醒道德是非；自豪作案且毫无道德顾虑与听从良心矛盾。')],quiz:[q('conscience',1,1,'A person’s conscience helps them judge?','whether an action is right or wrong','how far a place is from home','which food contains more salt','conscience.s1 是道德是非感。'),q('conscience',2,1,'Someone with a clear conscience feels?','free of guilt about their actions','unable to see in daylight','certain that every rumor is true','clear conscience 表示没有内疚。'),q('conscience',3,1,'Which action is guided by conscience?','Returning money that was accidentally overpaid','Keeping the money while hiding the mistake','Blaming an innocent person','主动归还多付的钱体现良心判断。'),q('conscience',4,1,'“A matter of conscience” is a matter of?','personal moral judgment','river geography','computer configuration','该表达涉及个人道德判断。')]});
  D('conscious',{etymology:e('conscious','conscious 经法语源自拉丁语 conscius「共同知晓、知道的」，与 conscire「共同知道」相关；英语中发展为有意识或察觉到。','表示清醒有意识，或意识到某人、某事；常用 conscious of。'),contexts:[c('conscious.s1','事故现场','After the fall, the cyclist remained conscious and could tell the paramedic her name and where her helmet was.','摔倒后，骑车人仍有意识，能告诉急救员自己的姓名和头盔的位置。','After the fall / the cyclist remained conscious / and could tell the paramedic her name and where her helmet was.','remain conscious 表示保持清醒；where 引导间接疑问从句。','能够回应急救员说明她没有失去意识。')],mistakes:[m('The patient was conscious throughout the operation, although she was completely unconscious and could not respond.','The patient was unconscious throughout the operation and could not respond.','完全无意识且无法回应与 conscious 相反。')],quiz:[q('conscious',1,1,'A conscious patient is?','awake and aware','asleep and unresponsive','unaware of all surroundings','conscious.s1 指有意识、清醒的。'),q('conscious',2,1,'If someone is conscious of a risk, they?','are aware of it','have forgotten it entirely','caused it deliberately','conscious of 表示意识到某事。'),q('conscious',3,1,'Which person is conscious?','A patient answers questions after an accident.','A patient cannot be awakened or respond.','An empty chair in the room','能应答的患者仍有意识。'),q('conscious',4,1,'Choose the natural phrase.','She was conscious of the warning.','She was conscious to the warning.','She conscioused the warning.','常用结构为 conscious of something。')]});
  D('consciously',{etymology:e('consciously','consciously 由 conscious 加副词后缀 -ly 构成；conscious 经法语来自拉丁语 conscius「知晓的」。','可表示带着充分意识行事，也可强调行为是有意而非偶然。'),contexts:[c('consciously.s2','行为意图','Mira consciously chose not to interrupt her colleague, waiting until the presentation ended before raising her objection.','米拉有意选择不打断同事，等演讲结束后才提出反对意见。','Mira consciously chose not to interrupt her colleague / waiting until the presentation ended / before raising her objection.','consciously 修饰 chose，强调经过有意选择；until 引导等待的时间界限。','她刻意控制发言时机，对应“有意地”义。')],mistakes:[m('He consciously pressed the button by accident while insisting he had no intention of touching it.','He accidentally pressed the button while insisting he had no intention of touching it.','by accident 表示偶然；与 consciously 所强调的有意行为冲突。')],quiz:[q('consciously',1,1,'To act consciously is to act?','with awareness of what one is doing','while completely unconscious','without noticing anything','consciously.s1 指清醒、有意识地行动。'),q('consciously',2,2,'She consciously avoided the topic. She avoided it?','on purpose','by accident','without realizing it existed','consciously.s2 强调刻意、有意。'),q('consciously',3,2,'Which choice was made consciously?','He deliberately paused before answering.','She tripped without seeing the step.','The light went out unexpectedly.','deliberately 表示有意，符合刻意义。'),q('consciously',4,1,'A driver consciously checks the mirror because the driver?','knows they are doing it','is asleep at the wheel','has no awareness of the road','带着意识检查镜子体现 consciously。')]});
  D('conscription',{etymology:e('conscription','conscription 源自拉丁语 conscriptio「登记、征召」，与 conscribere「共同写入、登记」相关；conscript 原指编入名册。','指政府强制登记并征召人员服兵役，亦称征兵制。'),contexts:[c('conscription.s1','公共政策','The legislature debated conscription after the government announced that all eligible adults might be called into military service during the emergency.','政府宣布紧急时期可能征召所有符合条件的成年人入伍后，议会开始辩论征兵制。','The legislature debated conscription / after the government announced / that all eligible adults might be called into military service during the emergency.','conscription 作 debated 的宾语；that 从句说明政策内容。','强制将人员征入军队体现征兵义。')],mistakes:[m('The country ended conscription and made military service voluntary, requiring every citizen to enlist by law.','The country ended conscription and made military service voluntary, so citizens could choose whether to enlist.','强制依法入伍与自愿服役是相反制度。')],quiz:[q('conscription',1,1,'Conscription is?','compulsory military service enrollment','voluntary retirement from the army','a system for electing lawmakers','conscription.s1 指强制服兵役或征兵。'),q('conscription',2,1,'Under conscription, eligible people may be?','required by law to join military service','paid to avoid every public duty','asked only to vote in an election','征兵制可依法强制符合条件者服役。'),q('conscription',3,1,'Which policy uses conscription?','The state drafts citizens into the armed forces.','The state invites volunteers but imposes no duty.','The state closes a military museum.','国家征召公民入伍体现 conscription。'),q('conscription',4,1,'A debate about conscription concerns?','whether service should be compulsory','how rivers join','whether information is confidential','征兵争论的核心是服役是否强制。')]});
  D('consecrate',{etymology:e('consecrate','consecrate 经法语来自拉丁语 consecrare「奉献、使神圣」，由 con-「共同、完全」与 sacrare「奉为神圣」相关成分构成。','可指正式奉献给神圣或崇高事业、通过宗教仪式祝圣，也可作形容词表示已奉献的。'),contexts:[c('consecrate.s2','宗教仪式','The bishop will consecrate the new chapel after its altar and stained-glass windows have been completed.','祭坛和彩绘玻璃窗完工后，主教将为这座新礼拜堂举行祝圣仪式。','The bishop will consecrate the new chapel / after its altar and stained-glass windows have been completed.','consecrate 是及物动词，chapel 作宾语；after 从句说明仪式时间。','主教通过仪式将礼拜堂正式祝圣，符合 s2。')],mistakes:[m('The bishop consecrated the chapel by formally declaring that it must never be used for any religious purpose.','The bishop consecrated the chapel by formally dedicating it for religious use.','奉为神圣与明确禁止任何宗教用途相矛盾。')],quiz:[q('consecrate',1,1,'To consecrate one’s life to a cause is to?','devote it formally to that purpose','spend it on an unrelated hobby','keep it secret from everyone','consecrate.s1 指奉献给神圣或崇高事业。'),q('consecrate',2,2,'A religious leader may consecrate a church by?','declaring it holy in a ceremony','selling it as a private home','removing its altar permanently','consecrate.s2 指通过仪式祝圣场所。'),q('consecrate',3,3,'A consecrated building is one that is?','devoted to a holy purpose','undergoing ordinary road repairs','kept secret as a private password','形容词义表示已经奉献、具有神圣用途。'),q('consecrate',4,2,'Which event is a consecration?','A bishop performs a rite to make a chapel holy.','A builder measures the chapel’s roof.','A visitor takes a photograph outside.','祝圣仪式赋予场所宗教上的神圣地位。')]});
  D('consecutively',{etymology:e('consecutively','consecutively 由 consecutive 加副词后缀 -ly 构成；consecutive 来自拉丁语 consecutivus，与 consequi「跟随、接续」相关。','表示一个接一个、顺序连续地发生，中间没有间断。'),contexts:[c('consecutively.s1','赛事记录','Marta won three consecutive heats, finishing first in each one before the final began on Saturday.','玛尔塔连续赢得三轮预赛，在周六决赛开始前每轮都名列第一。','Marta won three consecutive heats / finishing first in each one / before the final began on Saturday.','consecutive 修饰 heats，意为连续的；each one 指每一轮。','三轮紧接着进行且每次获胜体现连续性。')],mistakes:[m('He missed four consecutive days of class, attending Monday and then returning a month later with no other absence.','He missed four separate days of class, with weeks between them.','consecutive 表示顺次接连；中间隔数周的缺席并非连续。')],quiz:[q('consecutively',1,1,'Three days spent consecutively are days that occur?','one after another without a break','only on alternating weeks','at unrelated times','consecutively.s1 指不间断地接连发生。'),q('consecutively',2,1,'A player wins five games consecutively by winning?','five games in a row','one game every five years','five games after losing each one','in a row 表示连续地。'),q('consecutively',3,1,'Which schedule has events consecutively?','Monday, Tuesday, and Wednesday sessions','sessions each month with long gaps','one session canceled each week','相邻三天连续安排活动。'),q('consecutively',4,1,'The opposite of consecutively is?','with interruptions','in a row','without a gap','consecutively 表示连续；有间断则相反。')]});
  D('consequent',{etymology:e('consequent','consequent 经古法语来自拉丁语 consequens「随后而来的」，是 consequi「跟随」的现在分词。','作名词指某行为的结果；作形容词表示由某事引起，或逻辑上随前提而来。'),contexts:[c('consequent.s1','环境影响','The consequent of the prolonged drought was a sharp decline in the reservoir level, forcing the city to restrict outdoor watering.','长期干旱的后果是水库水位大幅下降，迫使该市限制户外浇水。','The consequent of the prolonged drought / was a sharp decline in the reservoir level / forcing the city to restrict outdoor watering.','consequent 在此作名词，of 短语说明原因。','水位下降是长期干旱之后产生的结果。')],mistakes:[m('The consequent of the fire occurred before the fire began and had no relation to it.','The consequent of the fire occurred after it and was caused by it.','consequent 指随后产生的结果；发生在原因之前且无关联不能称为其后果。')],quiz:[q('consequent',1,1,'A consequent of an action is?','something that results from it','the action’s unrelated cause','a word linking two clauses','consequent.s1 是结果、后果。'),q('consequent',2,2,'A consequent delay is a delay that?','happens as a result of something','causes the original event','was planned years earlier','consequent.s2 作形容词表示由此导致的。'),q('consequent',3,3,'A conclusion consequent on the evidence is?','logically following from it','contradicting every fact','unrelated to the argument','consequent.s3 可指逻辑上随前提得出。'),q('consequent',4,1,'If flooding is a consequent of heavy rain, flooding is?','an outcome of the rain','the rain’s earlier cause','a type of cloud','结果义表示由降雨引发的后续事件。')]});
  D('conservationist',{etymology:e('conservationist','conservationist 由 conservation 加 -ist 构成；conservation 源自拉丁语 conservare「保存、保护」，由 con- 与 servare「守护」组成。','可指保护自然资源的人，也可指修复保护历史建筑或艺术品的专业人员。'),contexts:[c('conservationist.s1','自然保护','The conservationist mapped nesting sites and worked with local farmers to reduce pesticide use near the wetland.','自然保护工作者绘制了鸟类筑巢地点，并与当地农民合作减少湿地附近的农药使用。','The conservationist mapped nesting sites / and worked with local farmers / to reduce pesticide use near the wetland.','conservationist 作主语；to-infinitive 表示合作目标。','保护湿地生境和物种属于自然保护工作。')],mistakes:[m('The conservationist proposed draining the wetland and removing every nesting habitat to protect local wildlife.','The conservationist proposed protecting the wetland and preserving nesting habitat for local wildlife.','破坏栖息地与保护自然资源的 conservationist 职责相反。')],quiz:[q('conservationist',1,1,'A conservationist works to protect?','nature and natural resources','only a company’s profit margin','old recipes from change','conservationist.s1 指自然资源保护者。'),q('conservationist',2,2,'A conservationist restoring an old painting is protecting?','a work of art','a river’s traffic flow','a political constituency','conservationist.s2 可指文物或艺术品保护者。'),q('conservationist',3,1,'Which task suits a wildlife conservationist?','preserving habitat for endangered birds','paving over a nesting marsh','increasing illegal hunting','保护栖息地是自然保护工作。'),q('conservationist',4,2,'A museum conservationist may specialize in?','repairing and preserving historic objects','drafting a national constitution','treating constipation','conservationist.s2 涉及文物保护修复。')]});
  D('conservatism',{etymology:e('conservatism','conservatism 由 conservative 加 -ism 构成；conserve 经古法语来自拉丁语 conservare「保存、保护」。','可指维护传统、抵制剧变的政治思想，也可指做事谨慎、避免风险的态度。'),contexts:[c('conservatism.s2','投资策略','The fund manager’s conservatism led her to keep a large cash reserve rather than risk the clients’ savings on an untested venture.','基金经理的谨慎作风使她保留大量现金，而没有把客户储蓄押在未经验证的创业项目上。','The fund manager’s conservatism led her to keep a large cash reserve / rather than risk the clients’ savings / on an untested venture.','conservatism 作主语；rather than 对比谨慎与冒险选择。','避免风险、采取保守策略体现 s2。')],mistakes:[m('The manager’s conservatism was shown by investing every client’s savings in the riskiest untested venture available.','The manager’s risk-taking was shown by investing every client’s savings in the riskiest untested venture available.','把全部资金投向最高风险项目体现冒险，而非谨慎作风。')],quiz:[q('conservatism',1,1,'Political conservatism generally favors?','preserving traditions and resisting sudden change','replacing every institution immediately','ending all customary practices','conservatism.s1 指维护传统的政治思想。'),q('conservatism',2,2,'Financial conservatism often means?','caution and avoidance of unnecessary risk','spending all savings on speculation','refusing to examine any account','conservatism.s2 是谨慎、避险的态度。'),q('conservatism',3,1,'A party that emphasizes keeping established institutions shows?','conservatism','confluence','congestion','维护现存传统和制度体现政治保守主义。'),q('conservatism',4,2,'A cautious editor who changes little may be said to show?','conservatism','conjecture','confrontation','谨慎少改体现一般意义的保守作风。')]});
  D('conservatory',{etymology:e('conservatory','conservatory 经法语或拉丁语 conservatorium「保存之所」进入英语，与 conservare「保存、保护」相关。','英式英语常指温室或玻璃花房，也可指音乐或表演艺术学院；另有保护性的形容词用法。'),contexts:[c('conservatory.s2','音乐教育','After studying piano at the conservatory for five years, Elena auditioned for the orchestra’s young performers program.','在音乐学院学习钢琴五年后，埃琳娜参加了乐团青年演奏者项目的试演。','After studying piano at the conservatory for five years / Elena auditioned / for the orchestra’s young performers program.','conservatory 是 at 的宾语，指专业音乐学院。','长期学琴并参加演奏选拔符合学院义。')],mistakes:[m('She enrolled at the conservatory to study violin, although it was only a glass room for growing tropical plants.','She enrolled at the music conservatory to study violin.','仅供种植物的玻璃温室不是提供专业音乐训练的学院。')],quiz:[q('conservatory',1,1,'A gardener may grow seedlings in a conservatory that is?','a glass building for plants','a court for legal trials','a room for storing coins','conservatory.s1 指玻璃温室。'),q('conservatory',2,2,'A pianist attends a conservatory to?','study music professionally','grow tomatoes commercially','join a congressional committee','conservatory.s2 指音乐或表演艺术学院。'),q('conservatory',3,3,'A conservatory measure is intended to?','preserve or protect something','make it disappear','cause traffic to jam','conservatory.s3 表示保护性的。'),q('conservatory',4,2,'A violin student might apply to a?','conservatory','constellation','confluence','音乐学院是专业学习小提琴的场所。')]});
  D('considerably',{etymology:e('considerably','considerably 由 considerable 加副词后缀 -ly 构成；considerable 来自拉丁语 considerare「观察、思量」，后发展为“相当大、显著”。','修饰形容词或动词，表示程度显著、相当地。'),contexts:[c('considerably.s1','数据比较','After the insulation was replaced, the building used considerably less energy during the same winter months than it had the year before.','更换隔热材料后，这栋建筑在同一冬季月份的能耗比前一年显著降低。','After the insulation was replaced / the building used considerably less energy / during the same winter months than it had the year before.','considerably 修饰 less，强调程度差异；than 引出比较对象。','能耗下降幅度显著，体现“在很大程度上”。')],mistakes:[m('The second route was considerably longer, but the measured difference was only one centimeter on a map covering a thousand kilometers.','The second route was only slightly longer, with a one-centimeter difference on the map.','极小差异与 considerably 所强调的显著程度不相称。')],quiz:[q('considerably',1,1,'If a price rises considerably, it rises?','by a large or noticeable amount','by exactly zero','only in the buyer’s imagination','considerably.s1 表示相当地、显著地。'),q('considerably',2,1,'“The new route is considerably shorter” means it is?','much shorter','a little shorter only','exactly the same length','considerably 加强程度，意为短得多。'),q('considerably',3,1,'Which sentence uses considerably naturally?','The repair considerably reduced the noise.','The repair considerably the noise.','The repair reduced considerably to noise.','副词 considerably 修饰动词 reduced。'),q('considerably',4,1,'A considerably larger room is?','much larger','slightly smaller','the same size','considerably larger 表示大得多。')]});
  D('consign',{etymology:e('consign','consign 经法语源自拉丁语 consignare「盖印、托付」，由 con- 与 signare「标记、盖印」相关成分构成。','可正式交付给某人保管、托运货物，也可指把某人置于不利境地。'),contexts:[c('consign.s2','物流与寄售','The artist consigned six framed prints to the gallery, which agreed to display them and send her the proceeds after each sale.','艺术家把六幅装框版画寄售给画廊；画廊同意展出，并在每件售出后把所得款项寄给她。','The artist consigned six framed prints to the gallery / which agreed to display them / and send her the proceeds after each sale.','consign goods to a seller/gallery 表示托付代售；which 从句说明画廊安排。','作品交给画廊代售而非直接卖出，符合 s2。')],mistakes:[m('The gallery consigned the prints by refusing to take custody of them and never displaying or selling them.','The gallery accepted the prints on consignment and agreed to display and sell them.','consign goods to a gallery 是托付代售；拒绝接收不构成寄售。')],quiz:[q('consign',1,1,'To consign a duty to someone is to?','entrust or hand it over to them','erase the duty from every record','hide it from the person responsible','consign.s1 指正式托付或交付。'),q('consign',2,2,'An artist consigns paintings to a gallery so the gallery can?','display and sell them on the artist’s behalf','destroy them immediately','change the artist’s name','consign.s2 指将货物交给他人代售或保管。'),q('consign',3,3,'To consign a prisoner to a harsh fate is to?','put the prisoner into that unpleasant situation','set the prisoner free with no conditions','invite the prisoner to a celebration','consign.s3 表示把某人置于不利境地。'),q('consign',4,2,'Which arrangement is a consignment?','A shop sells goods for their owner and later pays the owner.','A customer buys an item outright and takes it home.','A carrier refuses to accept any parcel.','代售后再结算货款是寄售。')]});
  D('consignment',{etymology:e('consignment','consignment 由 consign 加 -ment 构成；consign 经法语源自拉丁语 consignare「托付、盖印」。','指一次交付或托运的一批货物，常由代理人代为保管或销售。'),contexts:[c('consignment.s1','仓储运输','The warehouse checked each consignment against its manifest before loading the boxes onto the truck bound for the regional depot.','仓库将每批托运货物与货单核对后，才把箱子装上开往地区仓库的卡车。','The warehouse checked each consignment against its manifest / before loading the boxes / onto the truck bound for the regional depot.','each consignment 作 checked 的宾语；against a manifest 表示对照货单核查。','同批交付并运输的一组货物对应 s1。')],mistakes:[m('The carrier logged a consignment of one thousand boxes as a single loose apple with no shipment records.','The carrier logged the consignment as a shipment of one thousand boxes with its manifest.','一整批货物不应被记作单个散装苹果，且托运应有对应记录。')],quiz:[q('consignment',1,1,'A consignment is?','a batch of goods delivered together','one private opinion','a law passed by a congress','consignment.s1 指一批托运或交付货物。'),q('consignment',2,1,'A store receiving a consignment may?','sell the goods for their owner','own the goods before they arrive','send no goods and keep no record','寄售货物可交商店代为销售。'),q('consignment',3,1,'A shipment manifest lists items in a?','consignment','conscience','conservatory','货单会列出同批托运货物。'),q('consignment',4,1,'Several crates delivered as one shipment form a?','consignment','confrontation','constellation','同一次交付的一批箱子可称 consignment。')]});
  D('consolidation',{etymology:e('consolidation','consolidation 由 consolidate 加 -ion 构成；consolidate 经法语来自拉丁语 consolidare「使坚固」，由 con- 与 solidare「使坚实」组成。','指权力、成果或基础得到巩固，也指公司、债务等合并为一体。'),contexts:[c('consolidation.s2','企业并购','The consolidation of the two regional banks reduced duplicated branches and combined their online payment systems under one platform.','两家地区银行的合并减少了重复网点，并将它们的在线支付系统整合到一个平台。','The consolidation of the two regional banks / reduced duplicated branches / and combined their online payment systems under one platform.','consolidation of A and B 指二者合并；并列谓语说明结果。','两家银行整合成一个组织与系统，体现 s2。')],mistakes:[m('The consolidation of the firms left them as separate competitors with unrelated systems and no shared operations.','The separation of the firms left them as separate competitors with unrelated systems and no shared operations.','保持完全独立、没有整合是分立而非 consolidation。')],quiz:[q('consolidation',1,1,'The consolidation of political power is its?','strengthening and stabilization','complete disappearance','transfer to unrelated countries','consolidation.s1 指巩固加强。'),q('consolidation',2,2,'Consolidation of two companies means?','merging them into one organization','splitting one company into many','closing both without a successor','consolidation.s2 指企业或债务合并。'),q('consolidation',3,1,'A leader consolidates gains by?','making recent achievements more secure','immediately giving them all up','pretending no gains occurred','巩固成果是使已取得的进展更稳固。'),q('consolidation',4,2,'Combining several loans into one new loan is debt?','consolidation','confrontation','connotation','将多笔债务合并成一笔是 debt consolidation。')]});
  D('consonant',{etymology:e('consonant','consonant 经法语来自拉丁语 consonans「共同发声」，由 con-「一起」与 sonare「发声」构成。','可指发音时气流受阻或变窄的辅音，也可作形容词表示与某观点一致。'),contexts:[c('consonant.s2','观点协调','The proposed schedule was consonant with the union agreement because it preserved the required rest periods between shifts.','拟议的排班与工会协议一致，因为它保留了班次之间规定的休息时间。','The proposed schedule was consonant with the union agreement / because it preserved the required rest periods / between shifts.','be consonant with 表示与……一致；because 从句说明一致依据。','排班满足协议要求，体现协调一致义。')],mistakes:[m('The new policy was consonant with the agreement even though it directly violated every clause in it.','The new policy was inconsistent with the agreement because it directly violated every clause in it.','违反协议所有条款与“相一致”的 consonant 相反。')],quiz:[q('consonant',1,1,'A consonant sound is produced with?','airflow blocked or narrowed in the vocal tract','no movement of air through the mouth ever','a melody played by an orchestra','consonant.s1 指辅音音素或字母。'),q('consonant',2,2,'A decision consonant with the rules is?','in agreement with them','in direct conflict with them','unrelated to them','consonant.s2 指相一致、协调。'),q('consonant',3,1,'Which letter usually represents a consonant sound?','b','a','e','b 通常表示辅音；a、e 通常表示元音。'),q('consonant',4,2,'The findings are consonant with the theory. The findings?','support or agree with the theory','disprove the theory','have no connection to it','be consonant with 表示与理论相符。')]});
  D('constancy',{etymology:e('constancy','constancy 经古法语来自拉丁语 constantia「坚定、稳定」，与 constare「站稳、保持不变」相关。','表示状态不变，或对某人、信念保持忠诚坚定。'),contexts:[c('constancy.s1','长期观测','The constancy of the lighthouse beam allowed ships to use it as a reliable landmark through changing weather.','灯塔光束的稳定性使船只在天气变化时仍能把它当作可靠地标。','The constancy of the lighthouse beam / allowed ships to use it / as a reliable landmark through changing weather.','constancy 作主语；of 短语说明保持稳定的对象。','光束持续稳定，体现不变性。')],mistakes:[m('The machine’s constancy was praised even though its readings changed wildly every minute.','The machine’s inconsistency was evident because its readings changed wildly every minute.','读数剧烈波动说明不稳定，而非 constancy。')],quiz:[q('constancy',1,1,'The constancy of a signal is its?','steadiness over time','sudden disappearance','ability to change randomly','constancy.s1 指恒定、稳定。'),q('constancy',2,1,'Constancy in a friendship may mean?','loyal and steady support','frequent betrayal','a lack of contact by definition','对朋友持续忠诚体现坚定不移。'),q('constancy',3,1,'Which shows constancy of temperature?','The reading stays nearly the same all day.','The reading jumps up and down each minute.','The thermometer is missing.','读数长时间基本不变体现恒定。'),q('constancy',4,1,'The closest opposite of constancy is?','instability','steadfastness','regularity','instability 是不稳定，与 constancy 相反。')]});
  D('constellation',{etymology:e('constellation','constellation 经古法语来自拉丁语 constellatio「星群」，由 con-「共同」与 stella「星」组成。','可指夜空中被看作图形的一组星，也可比喻一群杰出人物或一组相关事物。'),contexts:[c('constellation.s1','天文学','On a clear winter night, the guide pointed out the constellation Orion and showed visitors how to locate its three bright belt stars.','冬夜晴朗时，向导指出猎户座，并向游客展示如何辨认腰带上的三颗亮星。','On a clear winter night / the guide pointed out the constellation Orion / and showed visitors how to locate its three bright belt stars.','constellation 后接名称 Orion；how 引导说明辨认方法的从句。','猎户座是夜空中被命名的一组星。')],mistakes:[m('The astronomer called Orion a constellation of five separate galaxies spread across different universes.','The astronomer called Orion a constellation, a named pattern of stars seen in the night sky.','星座是从地球视角识别的一组星，不是分布在不同宇宙的星系。')],quiz:[q('constellation',1,1,'A constellation is a recognized pattern of?','stars in the night sky','clouds in a thunderstorm','letters in a legal document','constellation.s1 指星座或星群。'),q('constellation',2,2,'A constellation of musicians is?','a distinguished group of musicians','a map of the stars only','a group of unrelated rivers','constellation.s2 可比喻杰出人物群体。'),q('constellation',3,1,'Orion is an example of a?','constellation','conservatory','consonant','猎户座是星座名称。'),q('constellation',4,2,'A constellation of problems means?','a group of related problems appearing together','one solved problem','a telescope that sees no stars','比喻义指一组共同出现的人或事物。')]});
  D('consternation',{etymology:e('consternation','consternation 经法语来自拉丁语 consternare「使惊慌、使震惊」，与 sternere「击倒、使惊愕」相关。','指突发震惊与担忧交织、使人一时不知所措的感受。'),contexts:[c('consternation.s1','突发公告','To the team’s consternation, the venue announced that the event had been canceled only an hour before the doors were due to open.','令团队惊愕不安的是，场地方在原定开门前一小时才宣布活动取消。','To the team’s consternation / the venue announced that the event had been canceled / only an hour before the doors were due to open.','to someone’s consternation 是“令某人惊愕的是”；that 从句说明坏消息。','临近开场突然取消引起震惊和担忧。')],mistakes:[m('The announcement caused consternation, and everyone calmly expected it because it was routine and caused no concern.','The announcement caused no consternation because everyone expected it and felt no concern.','完全预料且毫不担心与惊愕不安的 consternation 不符。')],quiz:[q('consternation',1,1,'Consternation is a feeling of?','shock and worry that leaves one unsettled','quiet satisfaction with a routine event','physical hunger after exercise','consternation.s1 指惊愕、惊慌失措。'),q('consternation',2,1,'A sudden unexplained cancellation may cause?','consternation','congruity','constancy','意外坏消息可能使人震惊担忧。'),q('consternation',3,1,'“To my consternation” means?','to my shock and dismay','to my complete delight','without my knowledge of the subject','该短语表示令我惊愕或沮丧的是。'),q('consternation',4,1,'Which reaction shows consternation?','She stared in alarm after hearing the unexpected news.','She nodded calmly at the familiar schedule.','She laughed with relief after a good result.','意外消息后惊慌发愣是 consternation。')]});
  D('constipation',{etymology:e('constipation','constipation 经法语源自拉丁语 constipare「挤紧、塞住」，由 con- 与 stipare「压紧」构成；医学英语中指排便困难或不频繁。','医学术语，表示便秘；不用于一般道路拥堵。'),contexts:[c('constipation.s1','健康咨询','The pharmacist advised the patient to discuss persistent constipation with a clinician, especially because the symptom had lasted for several weeks.','药剂师建议患者就持续数周的便秘咨询临床医生，尤其是这一症状已经持续了好几周。','The pharmacist advised the patient / to discuss persistent constipation with a clinician / especially because the symptom had lasted for several weeks.','persistent 修饰 constipation；advise someone to do 表示建议某人做某事。','排便困难持续多周是便秘症状。')],mistakes:[m('The doctor diagnosed constipation because the patient had frequent, effortless bowel movements several times each day.','The doctor ruled out constipation because the patient had frequent, effortless bowel movements several times each day.','排便频繁且轻松与便秘的排便困难或不频繁表现相反。')],quiz:[q('constipation',1,1,'Constipation is a condition involving?','infrequent or difficult bowel movements','blocked traffic on a highway','difficulty hearing high notes','constipation.s1 是便秘。'),q('constipation',2,1,'Someone seeking advice for constipation should discuss?','their bowel symptoms with a healthcare professional','a river’s confluence','a voting district','该医学词涉及排便状况。'),q('constipation',3,1,'Which symptom is associated with constipation?','hard stools that are difficult to pass','a sore throat after singing','a sudden change in eyesight only','排便困难或粪便干硬是常见表现。'),q('constipation',4,1,'In a medical note, constipation refers to?','a digestive condition','a political policy','a type of tree','该词是消化系统相关的医学术语。')]});
  D('constituency',{etymology:e('constituency','constituency 由 constituent 加 -cy 构成；constituent 源自拉丁语 constituere「设立、组成」，由 con- 与 statuere「建立」组成。','可指选出代表的选区及其中选民，也可泛指依赖某人支持或服务的群体。'),contexts:[c('constituency.s1','选举制度','The candidate visited every town in her constituency and promised voters that she would hold monthly public meetings.','候选人走访了自己选区内的每个城镇，并向选民承诺每月举行公开会议。','The candidate visited every town in her constituency / and promised voters / that she would hold monthly public meetings.','constituency 指选区或该区选民；her 标明候选人的代表范围。','选区内居民投票选出代表，体现 s1。')],mistakes:[m('The district was not part of the representative’s constituency even though its residents had elected that representative.','The district was part of the representative’s constituency because its residents had elected that representative.','选民选出代表的地区就是其选区。')],quiz:[q('constituency',1,1,'A parliamentary constituency is?','a district represented by an elected member','a courtroom for criminal trials','a group of musical instruments','constituency.s1 指选区及其选民。'),q('constituency',2,2,'A teacher’s constituency may include?','the students and families the teacher serves','only the teacher’s desk','a district with no residents','constituency.s2 可指服务对象群体。'),q('constituency',3,1,'Voters in a constituency choose?','their representative','the weather forecast','the border of a river','选区选民投票选出代表。'),q('constituency',4,2,'A company’s consumer constituency is the group of people?','whose custom or support it relies on','who wrote its constitution','who live beside its office only','某组织的 constituency 可指其依赖的支持者或客户。')]});
  D('constitutional',{etymology:e('constitutional','constitutional 由 constitution 加 -al 构成；constitution 经法语来自拉丁语 constitutio「设立、规定」，与 constituere「建立」相关。','可指宪法相关或符合宪法，也可描述人的身体体质。'),contexts:[c('constitutional.s1','法律审查','The court ruled that the search was constitutional because officers had obtained a valid warrant before entering the apartment.','法院裁定这次搜查符合宪法，因为警员进入公寓前已经取得有效搜查令。','The court ruled that the search was constitutional / because officers had obtained a valid warrant / before entering the apartment.','constitutional 作表语；because 从句给出合宪的依据。','依法律程序取得搜查令，故行为被判符合宪法。')],mistakes:[m('The judge ruled the search constitutional even though officers entered without a warrant in violation of the governing law.','The judge ruled the search unconstitutional because officers entered without a warrant in violation of the governing law.','违反宪法或法律保障的搜查与 constitutional 相反。')],quiz:[q('constitutional',1,1,'A constitutional right is a right?','protected or defined by a constitution','unrelated to any law','granted only by a private club','constitutional.s1 指宪法规定或保护的。'),q('constitutional',2,2,'A constitutional weakness concerns someone’s?','physical makeup or health','district for voting','legal voting representative','constitutional.s2 可形容人的体质。'),q('constitutional',3,1,'A constitutional challenge asks whether a law?','is allowed under the constitution','has been printed clearly','has enough pages','合宪性审查判断法律是否符合宪法。'),q('constitutional',4,2,'A person’s constitutional type refers to their?','physical build or natural constitution','political district','written legal code','该形容词也可描述个人体质。')]});
  D('constrained',{etymology:e('constrained','constrained 是 constrain 的过去分词形容词；constrain 经古法语来自拉丁语 constringere「捆紧、束缚」，由 con- 与 stringere「拉紧」构成。','指因规则、压力或资源不足而受限制，也可描述举止拘谨不自然。'),contexts:[c('constrained.s1','资源规划','With the grant covering only essential repairs, the school was constrained by its budget and postponed the new science laboratory.','由于拨款只够支付必要维修，学校受预算所限，推迟了新科学实验室的建设。','With the grant covering only essential repairs / the school was constrained by its budget / and postponed the new science laboratory.','be constrained by 表示受到……限制；with 短语交代背景。','预算资源不足限制了学校可采取的行动。')],mistakes:[m('The project was constrained by its unlimited budget and complete freedom to spend without approval.','The project was unconstrained by budget limits and could spend freely without approval.','无限预算且无需审批意味着没有受到限制。')],quiz:[q('constrained',1,1,'A constrained plan is one that?','is limited by rules or available resources','has unlimited freedom and funding','has already been completed','constrained.s1 指受限制的。'),q('constrained',2,1,'A constrained smile may look?','stiff and unnatural','completely spontaneous','like a river crossing','形容举止时 constrained 表示拘谨不自然。'),q('constrained',3,1,'A project constrained by time must?','work within a limited schedule','continue forever with no deadline','ignore every resource limit','受时间约束的项目必须在有限时限内工作。'),q('constrained',4,1,'Which phrase is natural?','constrained by lack of funding','constrained with unlimited money','constrained at no limits','constrained by 表示受到某条件限制。')]});
  D('constraint',{etymology:e('constraint','constraint 经古法语来自拉丁语 constrictio「压紧、束缚」，与 constringere「捆紧」相关；英语中表示限制或强制压力。','可指限制行动的条件，也可表示迫使行为的力量或拘谨的自我克制。'),contexts:[c('constraint.s1','工程设计','The bridge design had to respect a strict weight constraint, so engineers selected lighter materials without reducing structural safety.','桥梁设计必须遵守严格的承重限制，因此工程师选用更轻的材料，同时不降低结构安全性。','The bridge design had to respect a strict weight constraint / so engineers selected lighter materials / without reducing structural safety.','constraint 作 respect 的宾语；so 引出限制条件带来的方案选择。','承重上限限制设计选择，体现 s1。')],mistakes:[m('The engineers described the unlimited load capacity as a severe constraint that prevented them from carrying anything.','The engineers described the weight limit as a constraint on what the bridge could carry.','无限承载能力不会限制桥梁可承受的重量。')],quiz:[q('constraint',1,1,'A budget constraint is?','a limit on available spending','permission to spend without limit','a list of completed purchases','constraint.s1 指限制或约束条件。'),q('constraint',2,2,'A person speaking with constraint may show?','forced restraint or stiffness','complete ease and spontaneity','a lack of any pressure','constraint.s2 可表示强制或拘谨。'),q('constraint',3,1,'Which is a constraint on a building project?','a fixed deadline and limited materials','unlimited time and resources','a finished inspection certificate only','截止时间和材料限制会制约工程。'),q('constraint',4,1,'Designers work within constraints by?','finding solutions that respect the limits','pretending no limits exist','removing every safety rule','在约束内设计意味着方案满足限制条件。')]});
  D('constrict',{etymology:e('constrict','constrict 源自拉丁语 constringere「捆紧、束缚」，经拉丁语或法语形式进入英语；过去分词为 constrictus。','可指物理上挤压变窄，也可比喻限制自由、发展或活动空间。'),contexts:[c('constrict.s1','生理与解剖','Cold air can cause the small blood vessels in the skin to constrict, reducing blood flow near the body’s surface.','冷空气会使皮肤中的小血管收缩，从而减少身体表面的血流。','Cold air can cause the small blood vessels in the skin to constrict / reducing blood flow / near the body’s surface.','cause A to constrict 表示使 A 收窄；现在分词短语说明结果。','血管管腔变窄、血流减少，体现物理收缩义。')],mistakes:[m('The elastic band constricted the opening by stretching it wider and making more room for air.','The elastic band widened the opening by stretching it and making more room for air.','扩宽开口与 constrict 所表达的挤压变窄相反。')],quiz:[q('constrict',1,1,'To constrict a tube is to?','squeeze it so its opening becomes narrower','stretch it until it widens','remove it without touching it','constrict.s1 指压缩变窄。'),q('constrict',2,2,'Rules that constrict artistic freedom?','limit its development','expand its possibilities','have no effect on it','constrict.s2 可比喻限制自由或发展。'),q('constrict',3,1,'Which action constricts a hose?','clamping it so less water can pass','cutting it into a wider opening','connecting it to a larger tank','夹紧软管使通道变窄是 constrict。'),q('constrict',4,2,'A policy may constrict a market by?','restricting the ways businesses can operate','removing all restrictions','increasing every option','规章限制经营空间可比喻为 constrict。')]});
  D('consul',{etymology:e('consul','consul 经古法语或拉丁语 consul 进入英语；拉丁词源传统上与 consultare「商议」联系，古罗马执政官为最高公职之一。','现代常指驻外国城市、协助本国公民的领事；古罗马义指两名最高执政官之一。'),contexts:[c('consul.s1','领事服务','When her passport was stolen abroad, Lina contacted the nearest consul for help obtaining emergency travel documents.','莉娜在国外护照被盗后，联系最近的领事寻求帮助，以取得紧急旅行证件。','When her passport was stolen abroad / Lina contacted the nearest consul / for help obtaining emergency travel documents.','consul 是 contacted 的宾语；for help 表明联系领事的目的。','领事协助本国公民处理海外事务，符合现代义。')],mistakes:[m('The traveler asked the consul to rule ancient Rome as one of its two elected chief magistrates.','The traveler asked a Roman consul to serve as one of ancient Rome’s two chief magistrates.','在国外协助公民的现代领事，不负责统治古罗马。')],quiz:[q('consul',1,1,'A modern consul may help citizens?','of their country while they are abroad','vote in a local school election','grow plants in a conservatory','consul.s1 指驻外领事。'),q('consul',2,2,'In ancient Rome, a consul was?','one of the chief rulers of the republic','a modern passport clerk only','a provincial poet','consul.s2 指古罗马最高执政官。'),q('consul',3,1,'A traveler who loses a passport overseas might contact a?','consul','connoisseur','conservationist','领事可协助本国公民办理紧急旅行文件。'),q('consul',4,2,'The two consuls in the Roman Republic shared?','the highest executive office','a modern embassy’s reception desk','a market stall','古罗马两名执政官共同承担最高公职。')]});
  D('consultant',{etymology:e('consultant','consultant 由 consult 加施事后缀 -ant 构成；consult 经古法语来自拉丁语 consultare「商议、征求意见」，与 consulere「商议」相关。','可指受雇提供专业建议的顾问；英式医疗体系中特指医院高级专科医生。'),contexts:[c('consultant.s2','英国医疗','The patient’s general practitioner referred her to a hospital consultant, who reviewed the scans and recommended a specialist treatment plan.','全科医生把患者转诊给医院会诊医师；这位医生查看扫描结果后，建议了专科治疗方案。','The patient’s general practitioner referred her to a hospital consultant / who reviewed the scans / and recommended a specialist treatment plan.','hospital consultant 是英国医疗体系中的高级专科医生；who 从句描述其职责。','医院高级医生评估病例并提出治疗方案，符合 s2。')],mistakes:[m('The patient visited a UK hospital consultant for specialist care, but the consultant was merely a temporary hospital porter with no medical training.','The patient visited a UK hospital consultant, a senior doctor responsible for specialist care.','英式 consultant 是高级医生，不是无医学资质的搬运工。')],quiz:[q('consultant',1,1,'A business consultant is hired to?','give expert advice','repair every broken road','elect a representative','consultant.s1 指专业顾问。'),q('consultant',2,2,'In a UK hospital, a consultant is typically?','a senior specialist doctor','a patient’s visiting relative','a junior school teacher','consultant.s2 是医院高级专科医生。'),q('consultant',3,1,'A company seeking advice on cybersecurity may employ a?','consultant','consul','conservationist','提供专业建议的专家可聘作 consultant。'),q('consultant',4,2,'A hospital consultant may?','review a complex case and recommend treatment','vote on a city council budget','inspect a river’s confluence','高级医生负责专科评估与治疗建议。')]});
  D('consultation',{etymology:e('consultation','consultation 由 consult 加 -ation 构成；consult 经古法语来自拉丁语 consultare「商议、征求意见」。','指向医生或专家征求意见的会面，也指受影响者参与的讨论、磋商过程。'),contexts:[c('consultation.s2','公共政策','After a public consultation, the council revised the traffic plan to include concerns raised by residents and local shop owners.','公开征求意见后，市议会修改了交通方案，纳入居民和当地商户提出的关切。','After a public consultation / the council revised the traffic plan / to include concerns raised by residents and local shop owners.','public consultation 指征求公众意见；to include 表示修改目的。','方案在听取受影响群体意见后调整，体现 s2。')],mistakes:[m('The council called it a consultation but refused to hear from any residents affected by the plan.','The council called it a consultation and invited residents affected by the plan to give their views.','不征求受影响者意见，不符合咨询磋商过程的含义。')],quiz:[q('consultation',1,1,'A medical consultation is a meeting to?','get advice from a doctor','elect a member of parliament','repair a hospital roof','consultation.s1 指向医生或专家咨询。'),q('consultation',2,2,'A public consultation allows affected people to?','discuss a proposal and offer views','receive a medical prescription only','avoid hearing about the proposal','consultation.s2 指就提案征求意见。'),q('consultation',3,1,'A patient books a consultation with a specialist to?','discuss symptoms and receive expert advice','join the specialist’s company','inspect the specialist’s office lease','就症状向专家征求意见属于 consultation。'),q('consultation',4,2,'Before changing a neighborhood plan, officials may hold?','a consultation with residents','a congealing of residents','a constellation of roads','官员可通过征询居民意见完善方案。')]});
  D('consultative',{etymology:e('consultative','consultative 由 consult 加 -ative 构成；consult 经法语来自拉丁语 consultare「商议、征询」。','形容提供意见、以咨询为职责的机构或过程；通常侧重建议而非最终决策权。'),contexts:[c('consultative.s1','机构职能','The advisory panel has a consultative role: it reviews draft policies and offers recommendations, while elected officials make the final decisions.','该顾问小组承担咨询职能：审阅政策草案并提出建议，而最终决定由民选官员作出。','The advisory panel has a consultative role / it reviews draft policies and offers recommendations / while elected officials make the final decisions.','consultative 修饰 role；冒号后的说明突出建议与决策职责不同。','小组提供意见但不作最终决定，符合咨询性的用法。')],mistakes:[m('The consultative committee had sole final authority to enact every law without giving advice or hearing anyone.','The consultative committee advised decision-makers but did not hold final authority to enact laws.','只拥有最终立法权、又不提供建议，并非 consultative 职能。')],quiz:[q('consultative',1,1,'A consultative body mainly?','gives advice or recommendations','makes every final decision itself','keeps all proposals secret','consultative.s1 指咨询、提供建议的。'),q('consultative',2,1,'A consultative process usually invites?','expert or stakeholder input','automatic punishment','the cancellation of all discussion','咨询过程的核心是征求意见。'),q('consultative',3,1,'Which role is consultative?','An expert reviews a draft and recommends changes.','A judge issues a binding final ruling.','A clerk destroys the draft unseen.','提出修改建议而非作终局决定体现 consultative。'),q('consultative',4,1,'A consultative committee differs from a decision-making one because it?','advises rather than decides','never reads proposals','always controls the budget','该词强调咨询建议职责。')]});
  D('consumer',{etymology:e('consumer','consumer 由 consume 加施事后缀 -er 构成；consume 经古法语来自拉丁语 consumere「耗尽、使用」。','可指购买并使用商品服务的人，也可指消耗能量或资源的生物、设备等。'),contexts:[c('consumer.s1','市场服务','The consumer compared repair warranties and total costs before choosing the washing machine that best suited her household.','这位消费者比较了维修保修和总成本，之后才选择最适合家庭需要的洗衣机。','The consumer compared repair warranties and total costs / before choosing the washing machine / that best suited her household.','consumer 指购买并使用商品的人；that 从句修饰 washing machine。','对商品价格、保修进行比较并购买的人是消费者。')],mistakes:[m('The consumer bought and used the phone but was called a consumer only because she manufactured it for sale.','The consumer bought and used the phone; its manufacturer produced it for sale.','consumer 是购买、使用商品的人；生产商品的是 manufacturer。')],quiz:[q('consumer',1,1,'A consumer is a person who?','buys and uses goods or services','manufactures every product they buy','writes a country’s constitution','consumer.s1 指消费者。'),q('consumer',2,2,'An animal can be a consumer in an ecosystem because it?','uses energy by eating other organisms','writes a review of a product','represents a voting district','consumer.s2 可指生态系统中的资源消耗者。'),q('consumer',3,1,'A customer buying groceries is acting as a?','consumer','conservationist','conqueror','购买并使用食品的是消费者。'),q('consumer',4,2,'In ecology, a consumer obtains energy by?','feeding on plants or other organisms','creating sunlight','joining two rivers','生态学中的 consumer 通过摄食获取能量。')]});
  D('consumerism',{etymology:e('consumerism','consumerism 由 consumer 加 -ism 构成；consumer 由 consume 加 -er 而来。','可指把购买商品视为生活核心的消费主义，也可指保护消费者权利的运动。'),contexts:[c('consumerism.s2','消费者权益','The consumerism campaign pressed regulators to require clearer labels and a faster refund process for defective appliances.','消费者权益运动敦促监管机构要求更清晰的标签，并加快故障电器的退款流程。','The consumerism campaign pressed regulators / to require clearer labels / and a faster refund process for defective appliances.','consumerism 修饰 campaign，指维护买家权益的运动。','要求清楚披露信息和保障退款，体现消费者保护义。')],mistakes:[m('The consumerism group defended buyers by opposing clear labels, safe products, and access to refunds.','The consumerism group defended buyers by supporting clear labels, safe products, and access to refunds.','消费者权益运动旨在保障买方安全与知情权，而非反对这些保护。')],quiz:[q('consumerism',1,1,'Consumerism can describe a culture that?','places great importance on buying goods','rejects every form of trade','requires people to grow all food at home','consumerism.s1 指以消费购物为中心的倾向。'),q('consumerism',2,2,'A consumerism movement may work to?','protect buyers’ rights and safety','encourage hidden fees','prevent customers from reporting defects','consumerism.s2 指消费者权益保护运动。'),q('consumerism',3,1,'An advertisement encouraging constant shopping reflects?','consumerism','conscription','continence','鼓励把购买视为核心生活活动体现消费主义。'),q('consumerism',4,2,'A group seeking product-safety rules is part of?','consumerism advocacy','a constellation','a confluence','倡导买家安全和权利属于消费者保护运动。')]});
  D('contagion',{etymology:e('contagion','contagion 经古法语来自拉丁语 contagio「接触、传染」，与 contingere「接触」相关，由 con- 与 tangere「触碰」构成。','指接触传播的疾病，也可比喻情绪、观念或有害做法迅速蔓延。'),contexts:[c('contagion.s2','群体情绪','The contagion of panic spread through the station after a false alarm, even though officials quickly announced that the building was safe.','虚假警报后，恐慌情绪在车站内蔓延，尽管官员很快宣布建筑安全。','The contagion of panic spread through the station / after a false alarm / even though officials quickly announced that the building was safe.','contagion of panic 是恐慌情绪的蔓延；even though 引出反差。','一种情绪迅速传给周围人，体现比喻义。')],mistakes:[m('The contagion of panic remained with one person and did not affect anyone else in the crowded station.','The panic remained isolated in one person and did not spread through the station.','没有向他人蔓延就不是群体情绪的 contagion。')],quiz:[q('contagion',1,1,'Disease contagion is the?','spread of infection through contact','prevention of all illness','treatment of a broken bone','contagion.s1 指传染或接触感染。'),q('contagion',2,2,'The contagion of laughter describes laughter that?','spreads from person to person','is kept inside one locked room','is caused only by a medicine','情绪或行为的 contagion 指迅速蔓延。'),q('contagion',3,1,'A contagious illness may spread by?','contact between infected and uninfected people','reading a silent book alone','looking at an empty chair','contagion 与接触传播有关。'),q('contagion',4,2,'A contagion of optimism among workers means?','optimism spreads through the group','workers all become ill','no one shares any feeling','比喻义表示情绪或风气在群体中传播。')]});
  D('containerization',{etymology:e('containerization','containerization 由 container 加 -ization 构成；container 来自 contain 加施事后缀 -er，contain 经古法语来自拉丁语 continere「容纳、 удерживать」。','指采用标准化集装箱装运货物的运输体系或过程。'),contexts:[c('containerization.s1','国际物流','Containerization allowed the port to transfer sealed cargo units directly from ships to trains, cutting handling time and reducing damaged goods.','集装箱化使港口能把密封货运箱直接从船上转到火车上，缩短装卸时间并减少货物损坏。','Containerization allowed the port / to transfer sealed cargo units directly from ships to trains / cutting handling time and reducing damaged goods.','containerization 作主语；to transfer 说明带来的能力。','标准箱跨运输方式转运是集装箱化的特点。')],mistakes:[m('Containerization increased manual handling by removing standard containers and unpacking every item between each transport stage.','Containerization reduced manual handling by moving standardized containers between transport modes.','取消标准集装箱并反复拆包与集装箱化的目的相反。')],quiz:[q('containerization',1,1,'Containerization in freight transport means?','shipping goods in standardized containers','sending every item loose by hand','transporting passengers in a theater','containerization.s1 指货物集装箱化运输。'),q('containerization',2,1,'A containerized shipment can be moved?','between ships, trains, and trucks as a unit','only after every item is unpacked','only by people carrying each object','标准箱可作为整体在多种运输方式间转运。'),q('containerization',3,1,'A port adopts containerization mainly to?','speed cargo handling and transfer','make every shipment unpackable','replace all ships with buses','集装箱化提升货物装卸与转运效率。'),q('containerization',4,1,'Which innovation is central to containerization?','standard cargo units moved intact','unlabeled bags opened at every stop','a handwritten passenger list','标准化集装箱是该运输体系的核心。')]});
  D('contaminant',{etymology:e('contaminant','contaminant 由 contaminate 加名词后缀 -ant 构成；contaminate 源自拉丁语 contaminare「污染、玷污」，与 contagio「接触、传染」相关。','指使空气、水、食物或材料受到污染的物质或因素。'),contexts:[c('contaminant.s1','饮用水检测','The laboratory found a trace contaminant in the well water and advised residents to use bottled water until a second test was complete.','实验室在井水中发现微量污染物，并建议居民在第二次检测完成前使用瓶装水。','The laboratory found a trace contaminant in the well water / and advised residents / to use bottled water until a second test was complete.','contaminant 是 found 的宾语；trace 表示微量。','井水中的物质可能污染饮用水，符合污染物义。')],mistakes:[m('The inspector called clean distilled water a contaminant even though it introduced no harmful substance into the sample.','The inspector called the harmful chemical residue a contaminant because it polluted the sample.','不带入有害或污染性物质的洁净水不是 contaminant。')],quiz:[q('contaminant',1,1,'A contaminant is a substance that?','pollutes or makes another material unsafe','purifies every sample','measures a road’s length','contaminant.s1 指污染物。'),q('contaminant',2,1,'A contaminant detected in food may?','make the food unsafe','improve its nutrition automatically','turn it into a container','污染物可能使食品不安全。'),q('contaminant',3,1,'Which is a contaminant in drinking water?','harmful chemical residue','a harmless sealed glass bottle nearby','a clean measurement label','有害化学残留会污染饮用水。'),q('contaminant',4,1,'A lab removes a contaminant to?','reduce pollution in the sample','increase its contamination','change its name','移除污染物能降低样本污染。')]});
  D('contamination',{etymology:e('contamination','contamination 由 contaminate 加 -ion 构成；contaminate 源自拉丁语 contaminare「污染、玷污」，与 contagio「接触」相关。','可指污染行为或状态，也可指造成污染的有害物质。'),contexts:[c('contamination.s1','食品安全','The contamination of the spinach was traced to irrigation water that had been exposed to untreated waste upstream.','菠菜污染源头被追溯到受上游未经处理废水影响的灌溉水。','The contamination of the spinach / was traced to irrigation water / that had been exposed to untreated waste upstream.','contamination of 表示某物受到污染；that 从句修饰灌溉水。','污染过程及状态来自受废水影响的水源。')],mistakes:[m('The food was free from contamination, although inspectors found harmful bacteria throughout every tested portion.','The food was contaminated because inspectors found harmful bacteria throughout the tested portions.','各处检出有害细菌说明存在污染，不是无污染状态。')],quiz:[q('contamination',1,1,'Contamination is the act or state of?','making something dirty or unsafe','cleaning every harmful substance away','packing goods into containers','contamination.s1 指污染的行为或状态。'),q('contamination',2,2,'In some contexts, contamination can refer to?','harmful matter that spoils something pure','the clean material before exposure','a voter’s district','contamination.s2 可指污染物质本身。'),q('contamination',3,1,'A spill of toxic chemicals in a lake causes?','contamination','constancy','congruity','有毒化学物进入湖中会造成污染。'),q('contamination',4,2,'A harmful residue found in a food sample may be called?','contamination','consequent','constellation','该名词也可指污染样本的有害物质。')]});
  D('contemn',{etymology:e('contemn','contemn 源自拉丁语 contemnere「轻蔑、鄙视」，由 con- 与 temnere「轻视」构成；该词在现代英语中较少见且正式。','及物动词，表示认为某人或某事毫无价值而加以蔑视。'),contexts:[c('contemn.s1','文学评论','The narrator contemns the corrupt officials, describing how their greed harmed the people they had sworn to serve.','叙述者蔑视腐败官员，并描述他们的贪婪如何伤害了自己宣誓服务的民众。','The narrator contemns the corrupt officials / describing how their greed harmed the people / they had sworn to serve.','contemn 是及物动词，officials 作宾语；how 从句说明谴责缘由。','将腐败官员视为可鄙对象并蔑视他们，符合 contemn。')],mistakes:[m('She contemned the dishonest scheme by praising it as admirable and urging everyone to imitate it.','She condemned the dishonest scheme and urged everyone to reject it.','赞扬并提倡某事与蔑视、轻视它相矛盾。')],quiz:[q('contemn',1,1,'To contemn a dishonest act is to?','despise it as unworthy','praise it as admirable','copy it without question','contemn.s1 指蔑视、轻侮。'),q('contemn',2,1,'Which verb is closest to contemn?','despise','admire','repair','despise 表示鄙视，与 contemn 接近。'),q('contemn',3,1,'A writer who contemns cruelty?','regards it with scorn','celebrates it warmly','cannot recognize it','contemn 描述对残酷行为的鄙视。'),q('contemn',4,1,'“They contemn the corrupt practice” means they?','treat it as contemptible','consider it harmless and useful','join it secretly','contemn 表示看不起并认为其卑劣。')]});
  D('contemplation',{etymology:e('contemplation','contemplation 经古法语来自拉丁语 contemplatio「观察、沉思」，与 contemplari「仔细观察、考虑」相关。','可指安静深入的思考，也可指认真考虑某事作为可能计划。'),contexts:[c('contemplation.s2','行程规划','The team’s contemplation of a second research site ended when funding was reduced and the first location required additional staff.','经费削减且首个地点又需要增加人员后，团队放弃了对第二个研究地点的考虑。','The team’s contemplation of a second research site / ended / when funding was reduced / and the first location required additional staff.','contemplation of + 名词表示考虑某计划；when 引出决定变化时机。','团队把第二地点作为可能方案进行权衡，体现 s2。')],mistakes:[m('The board gave no contemplation to the expansion plan but claimed it had carefully weighed every option for months.','The board gave careful contemplation to the expansion plan and weighed its options for months.','完全没有考虑与声称长期仔细权衡矛盾。')],quiz:[q('contemplation',1,1,'Quiet contemplation involves?','serious, reflective thought','a loud argument between rivals','a sudden traffic blockage','contemplation.s1 指沉思、冥想。'),q('contemplation',2,2,'A plan under contemplation is?','being considered as a possible choice','already completed years ago','never mentioned or considered','contemplation.s2 表示正在盘算某计划。'),q('contemplation',3,1,'A person sits in contemplation to?','think deeply and quietly','announce a verdict immediately','compete in a race','安静深入地思考是 contemplation。'),q('contemplation',4,2,'“The firm is in contemplation of a merger” means it is?','considering a merger','celebrating a merger already completed','prohibiting all discussion','in contemplation of 表示正在考虑某事。')]});
  D('contemptible',{etymology:e('contemptible','contemptible 由 contempt 加 -ible 构成；contempt 经古法语来自拉丁语 contemptus「轻视」，与 contemnere「蔑视」相关。','表示行为卑劣、理应受鄙视；较少见义也可指微不足道、不值得关注。'),contexts:[c('contemptible.s1','公共诚信','The committee called the forged signatures contemptible because the fraud could have deprived elderly residents of their homes.','委员会称伪造签名的做法卑劣，因为这场欺诈可能夺走老年居民的住所。','The committee called the forged signatures contemptible / because the fraud could have deprived elderly residents of their homes.','contemptible 作宾语补足语；because 从句说明行为可鄙的原因。','利用伪造文件侵害弱势者，确实应受鄙视。')],mistakes:[m('The judge described the careful, honest charity work as contemptible and deserving of scorn.','The judge described the fraudulent, exploitative conduct as contemptible and deserving of scorn.','诚实助人行为不该被称为卑鄙可鄙；卑劣欺诈才符合。')],quiz:[q('contemptible',1,1,'A contemptible act deserves?','scorn because it is mean or cowardly','praise for its generosity','no attention because it is tiny','contemptible.s1 指卑劣、可鄙的。'),q('contemptible',2,2,'A contemptible amount may be?','too small to matter','morally admirable','impossible to measure because it is huge','contemptible.s2 可指小到不足挂齿。'),q('contemptible',3,1,'Which behavior is contemptible?','cheating a vulnerable person for personal gain','returning a lost wallet','admitting and correcting an error','趁弱者不备谋取私利是卑劣行为。'),q('contemptible',4,1,'A contemptible excuse is one that?','is so poor it deserves scorn','is fully convincing','has been confirmed by evidence','该词表示理由卑劣或不值得尊重。')]});
  D('contemptuous',{etymology:e('contemptuous','contemptuous 由 contempt 加 -uous 构成；contempt 经古法语来自拉丁语 contemptus「轻视」，与 contemnere「蔑视」同源。','形容流露轻蔑，或以认为别人低下的方式表现。'),contexts:[c('contemptuous.s1','职场沟通','The supervisor gave a contemptuous reply to the trainee’s question, implying that only an incompetent person would need the instruction.','主管轻蔑地回答实习生的问题，暗示只有无能的人才需要这项说明。','The supervisor gave a contemptuous reply / to the trainee’s question / implying that only an incompetent person would need the instruction.','contemptuous 修饰 reply；implying 补充轻蔑态度的表现。','言语表达鄙视和轻看对方，符合 s1。')],mistakes:[m('Her contemptuous response showed respect and admiration by thanking the colleague warmly for every useful suggestion.','Her appreciative response showed respect and admiration by thanking the colleague warmly.','诚恳感谢和赞赏表达尊重，不是轻蔑态度。')],quiz:[q('contemptuous',1,1,'A contemptuous remark shows?','scorn toward its target','warm admiration for its target','uncertainty about its spelling','contemptuous.s1 表示轻蔑、鄙视。'),q('contemptuous',2,2,'A contemptuous manner treats others as if they were?','inferior','equal and respected','unrelated to the speaker','contemptuous.s2 描述瞧不起人的行为方式。'),q('contemptuous',3,1,'Which expression sounds contemptuous?','“Only a fool would ask that question.”','“That is a thoughtful question.”','“Thank you for raising that point.”','把提问者贬作傻瓜表现出轻蔑。'),q('contemptuous',4,2,'A contemptuous look suggests the person feels?','superior and dismissive','grateful and impressed','afraid of the weather','该词形容以高人一等的姿态蔑视他人。')]});
  D('contender',{etymology:e('contender','contender 由 contend 加施事后缀 -er 构成；contend 经古法语来自拉丁语 contendere「努力、竞争」，由 con- 与 tendere「伸展、努力」组成。','指参与竞争的人，尤其是具有实际获胜机会的竞争者。'),contexts:[c('contender.s1','体育比赛','After setting a personal record in qualifying, the young runner became a serious contender for a medal in the final.','这位年轻跑者在预赛中刷新个人纪录后，成为决赛奖牌的有力竞争者。','After setting a personal record in qualifying / the young runner became a serious contender for a medal / in the final.','contender for + 奖项表示有望争夺该奖项的人。','预赛表现让其具备实际夺牌机会，符合 s1。')],mistakes:[m('The athlete was a contender for the title despite withdrawing before the race and having no chance to compete.','The athlete was not a contender for the title after withdrawing before the race.','退出比赛且无法参赛的人不再是有机会获胜的竞争者。')],quiz:[q('contender',1,1,'A strong contender for a title is?','a competitor with a real chance of winning','a spectator with no entry ticket','a judge who does not compete','contender.s1 指有望获胜的竞争者。'),q('contender',2,1,'Which person is a contender in an election?','a candidate competing for the office','a voter who stays home','a clerk who prints ballots only','参选争夺职位的候选人是 contender。'),q('contender',3,1,'A boxer becomes a contender by?','competing successfully for the championship','refusing to enter the tournament','selling tickets at the arena','有实力竞争拳击冠军者属于 contender。'),q('contender',4,1,'“A contender for the award” means?','someone competing to win it','someone who has already rejected it','someone who gives the award','contender for 表示争夺奖项的人。')]});
  D('contented',{etymology:e('contented','contented 由 content「满足」加过去分词后缀 -ed 构成；content 经古法语来自拉丁语 contentus「满足的」，与 continere「包含、足够」的历史联系有关。','形容对现状感到满足、安心，不一定意味着拥有很多。'),contexts:[c('contented.s1','家庭生活','After dinner, the contented child curled up with a library book, happy that the rainy evening had kept the family at home together.','晚饭后，这个满足的孩子蜷在一起看图书馆借来的书；下雨的夜晚让全家能待在家里相聚，他感到很开心。','After dinner / the contented child curled up with a library book / happy that the rainy evening had kept the family at home together.','contented 修饰 child；happy 补充孩子满足的状态。','对家庭相聚感到满足而安心，体现 contented。')],mistakes:[m('She felt contented with her life while insisting she was completely dissatisfied and wanted everything to change.','She felt discontented with her life and wanted everything to change.','完全不满并要求改变与知足安心的 contented 相矛盾。')],quiz:[q('contented',1,1,'A contented person feels?','satisfied and at ease','angry about every detail','confused by a simple direction','contented.s1 指满足、知足。'),q('contented',2,1,'Someone contented with a modest home?','is satisfied with it','must be planning to sell it','cannot live there','contented with 表示对某事感到满足。'),q('contented',3,1,'Which scene suggests a contented mood?','She relaxes happily after a pleasant meal.','She complains that nothing is acceptable.','She panics at every ordinary sound.','愉快地放松表现满足安心。'),q('contented',4,1,'Choose a close synonym for contented.','satisfied','restless','furious','satisfied 与 contented 都表示满足。')]});
  D('contention',{etymology:e('contention','contention 经古法语来自拉丁语 contentio「争论、竞争」，源自 contendere「努力竞争、争执」。','指激烈争论或争端，也可指辩论中提出的论点、主张。'),contexts:[c('contention.s2','论证写作','Her central contention is that the city should preserve the market because it provides affordable food as well as local jobs.','她的核心论点是市政府应保留这座市场，因为它既提供平价食品，也提供本地就业。','Her central contention is that the city should preserve the market / because it provides affordable food / as well as local jobs.','contention is that... 引出主张内容；because 从句提供理由。','她明确提出应保留市场的论点，符合 s2。')],mistakes:[m('The author’s contention was that the market should close, but she never expressed any opinion or position on it.','The author made no contention about whether the market should close because she expressed no position.','没有提出立场或主张就没有可称作 contention 的论点。')],quiz:[q('contention',1,1,'A heated contention between neighbors is?','an argument or dispute','a shared celebration','a quiet weather report','contention.s1 指争论或争端。'),q('contention',2,2,'“My contention is that the plan will save money” states?','the position I argue for','a rule that no one may discuss','a fact already withdrawn','contention.s2 指所持论点或主张。'),q('contention',3,2,'Which phrase introduces an argument’s main claim?','The author’s contention is that...','The author’s temperature is...','The author’s constellation is...','contention 可用来介绍作者的论点。'),q('contention',4,1,'A contention over land is most likely a?','dispute','medical consultation','coniferous forest','围绕土地的 contention 是争端。')]});
  D('contentious',{etymology:e('contentious','contentious 由 contention 加 -ious 构成；contention 经古法语源自拉丁语 contendere「争辩、竞争」。','可指容易引起争论的议题，也可描述爱争论、好挑衅的人。'),contexts:[c('contentious.s1','公共议题','The location of the new shelter remained contentious because residents disagreed about traffic, noise, and access to services.','新庇护所的选址仍有争议，因为居民对交通、噪声和服务可及性意见不一。','The location of the new shelter remained contentious / because residents disagreed about traffic, noise, and access to services.','contentious 作表语；because 从句列出分歧来源。','各方意见不一、容易引发争论，符合 s1。')],mistakes:[m('The proposal was contentious even though every group agreed immediately and no one raised an objection.','The proposal was uncontroversial because every group agreed immediately and no one raised an objection.','各方立即一致且无人反对，不属于容易引起争议的提案。')],quiz:[q('contentious',1,1,'A contentious issue is one that?','is likely to cause disagreement','has already been accepted by everyone','cannot be discussed because it is too small','contentious.s1 指有争议、易引发分歧的。'),q('contentious',2,2,'A contentious person tends to?','argue or pick quarrels','avoid every disagreement politely','work as a hospital consultant','contentious.s2 可形容好争吵的人。'),q('contentious',3,1,'Which topic is likely to be contentious?','a disputed policy that divides the community','a schedule all residents approved','a color no one has seen','引发社区分歧的政策容易引起争议。'),q('contentious',4,2,'A contentious colleague often?','turns discussions into arguments','settles every disagreement calmly','never expresses an opinion','好争论的人容易把讨论变成争吵。')]});
  D('contiguous',{etymology:e('contiguous','contiguous 源自拉丁语 contiguus「相接的、邻接的」，与 contingere「接触」相关，由 con- 与 tangere「触碰」组成。','一般表示紧邻；地理上常特指共享边界、无间隔相连的地区。'),contexts:[c('contiguous.s2','地理行政','The two contiguous counties share a border, allowing emergency crews to cross directly between them without entering another district.','这两个相连的郡共享边界，救援人员无需经过其他地区即可直接往来。','The two contiguous counties share a border / allowing emergency crews to cross directly between them / without entering another district.','contiguous 作定语修饰 counties；share a border 说明领土相接。','两郡边界相连且无间隔，符合 s2。')],mistakes:[m('The two parcels were contiguous although a wide public road and an unrelated property completely separated them.','The two parcels were nearby but not contiguous because a road and another property separated them.','有其他地块隔开时不共享边界，不能称领土 contiguous。')],quiz:[q('contiguous',1,1,'Two neighboring rooms are contiguous if they?','are very near or touch along a boundary','lie on different continents','cannot be reached from one another','contiguous.s1 可表示邻近、相接。'),q('contiguous',2,2,'Contiguous states share?','a border with no gap between them','only the same capital city','no geographic connection','地理义指领土相邻且共享边界。'),q('contiguous',3,2,'Which pair of plots is contiguous?','two plots sharing an edge','plots separated by a third property','plots on opposite sides of the ocean','共享一条边界的地块相连。'),q('contiguous',4,1,'The closest meaning of contiguous is?','adjacent','unrelated','distant','adjacent 表示邻接，与 contiguous 接近。')]});
  D('continence',{etymology:e('continence','continence 经法语来自拉丁语 continentia「自制、节制」，与 continere「控制、克制」相关；医学义也指控制排尿或排便的能力。','可指克制欲望，也可指大小便自控能力；需依据语境辨义。'),contexts:[c('continence.s2','护理与健康','After the neurological injury, the rehabilitation team assessed the patient’s continence and arranged support for managing bladder function.','神经损伤后，康复团队评估了患者的排泄控制能力，并安排膀胱功能管理支持。','After the neurological injury / the rehabilitation team assessed the patient’s continence / and arranged support for managing bladder function.','continence 作 assessed 的宾语；医学语境及 bladder function 指向生理自控义。','评估膀胱控制能力符合 s2。')],mistakes:[m('The nurse recorded continence even though the patient could not control urination or bowel movements at all.','The nurse recorded incontinence because the patient could not control urination or bowel movements.','无法控制排尿或排便应称失禁，而非 continence。')],quiz:[q('continence',1,1,'Continence as self-control means?','restraint over desires','a sudden loss of control','a river joining a lake','continence.s1 指自制、节制。'),q('continence',2,2,'Medical continence is the ability to control?','urination or bowel movements','blood pressure with no treatment','the movement of traffic','continence.s2 指排泄自控能力。'),q('continence',3,2,'A care plan addressing bladder continence concerns?','control of urination','a voting district','a disputed policy','膀胱控制属于 continence 的医学义。'),q('continence',4,1,'In a discussion of discipline, continence is closest to?','self-restraint','consternation','contamination','该语境下 continence 表示克制欲望。')]});
  D('contingency',{etymology:e('contingency','contingency 由 contingent 加 -cy 构成；contingent 经古法语源自拉丁语 contingere「发生、接触」，由 con- 与 tangere「触及」相关。','可指可能发生并造成麻烦的意外事件，也可指预先纳入计划的可能情况。'),contexts:[c('contingency.s2','应急预案','The hospital’s contingency plan included backup generators and a second water supply in case the main systems failed during a storm.','医院的应急预案包括备用发电机和第二水源，以防主系统在暴风雨期间故障。','The hospital’s contingency plan included backup generators and a second water supply / in case the main systems failed / during a storm.','contingency plan 是针对可能发生情况的预案；in case 引出假设情形。','停电或断水是可能事件，预案提前安排应对，符合 s2。')],mistakes:[m('The hospital’s contingency plan ignored all possible system failures and provided no backup for any emergency.','The hospital’s contingency plan listed possible failures and prepared backup systems for emergencies.','不考虑可能情况、也不设预案与 contingency planning 相反。')],quiz:[q('contingency',1,1,'An unexpected contingency is?','a possible event that may cause trouble','a guaranteed routine event','a completed action in the past','contingency.s1 指意外或突发状况。'),q('contingency',2,2,'A contingency plan prepares for?','a possible future event','only a past event that cannot recur','a meeting that has already ended','contingency.s2 指预案所针对的可能情况。'),q('contingency',3,2,'A backup generator is part of a contingency plan in case?','the main power supply fails','the lights are already on normally','the building is repainted','备用电源用于应对主供电可能故障。'),q('contingency',4,1,'Which is a contingency for an outdoor event?','unexpected severe weather','the scheduled opening time','a confirmed ticket purchase','突发恶劣天气属于可能影响活动的意外状况。')]});
})(globalThis);
